INSERT INTO `bidding_notice_external` VALUES (2096454639908225025,'1','2026-09-06 12:25:11','1','2026-09-07 09:24:32',_binary '\0','EBIDDING','秦源招标电子招标平台','炼化公司所属各单位2026年装置大修消缺公开招标公告','https://www.ebidding.com.cn/notice/detail?doc=DYZB2025-11-G141','194f300c065ada22aca278222773031feed4ad3df4866cc31ec18a9f90156648','2598dead07093fac4909c299255f6e672d5e64648efec6aac8e030c505fa13d3','HTML','<div class=\"notice-html-demo\"><h1>炼化公司所属各单位2026年装置大修消缺公开招标公告</h1><p>炼化公司所属各单位 2026年装置大修/消缺公开招标招标公告（招标编号：DYZB2025-11-G141）项目所在地区：炼化公司所属各单位一、招标条件本炼化公司所属各单位 2026年装置大修/消缺公开招标已由审批/核准/备案机关批准，项目资金来源为生产经营成本，出资比例 100%，招标人为陕西延长石油（集团）有限责任公司炼化公司，本项目已具备招标条件，现招标方式为公开招标。二、项目概况、招标范围和标段划分项目概况及范围：炼化公司所属各单位 2026年装置大修/消缺（主装置检修、辅助装置检修、电气检修、仪表检修、防腐保温施工、机组检修等）公开招标;共分为 7个标段。一标段：炼化公司 2026年延炼大修生产主装置安装检修项目；二标段：炼化公司 2026年石化厂、永炼、榆炼、油田气消缺检修/大修生产主装置安装检修项目；三标段：炼化公司 2026年延炼、永炼、榆炼、石化厂、油田气消缺检修/大修辅助装置安装检修项目；四标段：炼化公司 2026年延炼、永炼、榆炼、石化厂、油田气消缺检修/大修仪表检修项目；五标段：炼化公司 2026年延炼、永炼、榆炼、石化厂、油田气消缺检修/大修检修电气检修项目；六标段：炼化公司 2026年延炼、永炼、榆炼、石化厂、油田气消缺检修/大修防腐保温项目；七标段：炼化公司 2026年延炼、永炼、榆炼、石化厂、油田气消缺检修/大修机组检修项目。三、投标人资格要求1、投标人应为中华人民共和国境内依法注册的法人或其他组织，提供有效的营业执照或事业法人登记证书；2、具备一般纳税人资格，提供税务机关出具的一般纳税人资格证明，或近期开具的增值税专用发票记账联，或税务机关官方网站一般纳税人查询记录截图并附网址；3、一标段（主装置）：投标人需具备石油化工工程施工总承包贰级及以上资质;具有特种设备生产许可证（锅炉安装 A）；具有特种设备生产许可证（工业管道安装 GC1）；具有特种设备生产许可证（压力容器制造 D 级或以上）。拟派项目经理须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；二标段（主装置）：投标人需具备石油化工工程施工总承包贰级及以上资质；具有特种设备生产许可证（锅炉安装 A）；具有特种设备生产许可证（工业管道安装 GC1）；具有特种设备生产许可证（压力容器制造 D 级或以上）。拟派项目经理须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；三标段（辅助装置）：投标人需具备石油化工工程施工总承包贰级以上资质；具有特种设备生产许可证（锅炉安装 A）；具有特种设备生产许可证（工业管道安装 GC1）；具有特种设备生产许可证（压力容器制造 D 级或以上）。拟派项目经理及项目副经理各1人须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人 2人须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人 2人须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；四标段（仪表）：投标人需具备机电工程施工总承包贰级及以上资质或石油化工工程施工总承包贰级及以上资质。拟派项目经理及项目副经理各 1人，须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人 2人，须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人 2人，须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；五标段（电气）：投标人需具备机电工程施工总承包贰级及以上资质或国家承认的三级及以上承装（修、试）电力设施许可证。拟派项目经理及项目副经理各 1人，须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人 2人，须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人 2人，须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；六标段（防腐保温）：投标人需具备防水防腐保温工程专业承包壹级资质。拟派项目经理须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；七标段（机组检修）：投标人需具有石油化工工程施工总承包贰级及以上资质。拟派项目经理及项目副经理各 1人，须具备机电工程专业贰级建造师及以上资格，具有有效的安全生产考核合格 B证，且本项目实施期间未担任其他在建工程项目经理；拟派项目技术负责人 2人，须具备有效的与本项目相关专业有关的中级及以上职称证书；拟派项目安全负责人 2人须具有有效的安全生产考核合格 C证；以上人员同时需提供与本单位签订的有效劳动合同及本单位为其缴纳的至少连续一年以上社保证明(2024年 6月 1日起至今)；4、具有有效的安全生产许可证（1-7标段均需提供）；5、提供 2023年 1月 1日起至今，至少有一项类似施工或检维修合同业绩（一、二、三、四、五、六标段）；七标段所提供的业绩合同内容中应涵括烟气轮机、轴流式压缩机、离心式压缩机、往复压缩机及蒸汽轮机的机组检修业绩（可提供多份业绩证明，但所提供的业绩必须涵盖烟气轮机、轴流式压缩机、离心式压缩机、往复压缩机及蒸汽轮机的机组检修，如每份业绩只能体现以上一项不重复内容的，五份业绩算一份有效业绩）；6、不得列入国家企业信用信息公示系统经营异常名录、严重违法失信名单（黑名单），不得列入信用中国经营异常、严重失信主体名单，不得列入中国执行信息公开网失信被执行人名单；7、本次招标不接受联合体投标。四、招标文件的获取获取时间：从 2025年 11月 26日到 2025年 12月 3日。获取方式：本次招标实行网上获取招标文件。凡有意参加投标者，请于规定时间登录延长石油电子招标采购交易平台（网址：https://zc.ycpc.com）支付平台服务费后下载招标文件，平台服务费为 500.00元/标段，支付后不退。具体操作步骤如下：①登录延长石油电子招标采购交易平台（网址：https://zc.ycpc.com）按照提示信息进行投标人注册。②注册成功后，登录延长石油电子招标采购交易平台，查看“公告信息”，点击“参与项目”，并进入项目支付平台服务费，缴费成功后，在平台下载招标文件。③本项目采用电子招标方式，潜在投标人须使用 CA才能完成投标工作，潜在投标人办理 CA具体操作请参考延长石油电子招标采购交易平台的网站首页“帮助中心”的操作指引，在帮助中心界面下载 CA客户端、数字签名服务、投标编制工具。CA办理咨询电话：029-87302528或 029-81292135。④关于平台注册、操作、下载招标文件等有关交易平台、客户端的操作问题请咨询平台客服，咨询电话:张工 029-88445418。⑤关于财务及发票开票问题请联系 029-88444381（财务电话请核实），关于招标文件问题请联系 029-88443211。五、投标文件的递交递交截止时间：2025年 12月 22日 9时 00分递交方式：通过延长石油电子招标投标交易平台在线递交电子投标文件,逾期送达的投标文件，电子招标投标交易平台将予以拒收。六、开标时间及地点开标时间：2025年 12月 22日 9时 00分开标地点：延长石油电子招标投标交易平台在线开标，所有投标人可准时进入延长石油电子招标投标交易平台开标大厅参加在线开标仪式。七、发布公告的媒介本次招标公告同时在《陕西采购与招标网（www.sntba.com）》、《陕西省工业和信息化领域招标投标监管服务系统（https://61.185.253.156:8085/ztbView/newindex.html）》和《陕西延长石油招标采购交易平台（https://zc.ycpc.com）》上发布。八、监督部门本招标项目的监督部门为陕西省工业和信息化厅。九、联系方式招标人：陕西延长石油（集团）有限责任公司炼化公司地  址：陕西省延安市洛川县联系人：张勇电  话：13772880589</p><p>招标代理机构：陕西德源招标有限责任公司地址：陕西省西安市雁塔区科技二路 75号延长石油大厦联系人：马强电话：029-88443024电子邮件：703270390@qq.com</p></div>',NULL,NULL,NULL,NULL,NULL,'招标公告',NULL,'Y','BELONGS',0.9500,'DYZB2025-11-G141',NULL,NULL,'炼化公司所属各单位 2026年装置大修/消缺公开招标','陕西延长石油（集团）有限责任公司炼化公司','2026-09-06 12:25:11',NULL,NULL,'ACTIVE','APPROVED',NULL,'SOCIAL',2,'2026-09-06 16:46:30','NONE',NULL,NULL,NULL,'SUCCESS','{\"title\": \"炼化公司所属各单位2026年装置大修消缺公开招标公告\", \"issuer\": \"陕西延长石油（集团）有限责任公司炼化公司\", \"tenderNo\": \"DYZB2025-11-G141\", \"bidOpenTime\": \"2025-12-22 09:00:00\", \"projectName\": \"炼化公司所属各单位2026年装置大修/消缺公开招标\", \"budgetAmount\": null, \"contactPhone\": \"13772880589\", \"industryFlag\": \"BELONGS\", \"contactPerson\": \"张勇\", \"industryReason\": \"招标范围明确包含防腐保温施工标段，且涉及装置检修中的防腐保温工作，属于管道防腐保温行业。\", \"industryConfidence\": 0.95, \"industryHitKeywords\": \"[\\\"防腐保温\\\",\\\"装置检修\\\",\\\"管道\\\"]\", \"qualificationSummary\": \"投标人须为境内依法注册的法人或其他组织，具备一般纳税人资格；各标段需具备相应资质（如石油化工工程施工总承包贰级及以上、防水防腐保温工程专业承包壹级等），项目经理、技术负责人、安全负责人需满足相应资格并提供社保证明；具有有效的安全生产许可证；提供类似业绩；不得列入失信名单；不接受联合体投标。\"}','2026-09-06 14:56:19','AI_FALLBACK','SUCCESS','[{\"text\": \"炼化公司所属各单位2026年装置大修消缺公开招标公告\", \"type\": \"heading\", \"level\": 1}, {\"text\": \"发布日期：2025年11月26日\", \"type\": \"paragraph\"}, {\"text\": \"招标编号：DYZB2025-11-G141\", \"type\": \"paragraph\"}, {\"text\": \"项目所在地区：陕西省延安市洛川县\", \"type\": \"paragraph\"}, {\"text\": \"---\", \"type\": \"paragraph\"}, {\"text\": \"一、招标条件\", \"type\": \"heading\", \"level\": 2}, {\"text\": \"本炼化公司所属各单位2026年装置大修/消缺公开招标已由审批/核准/备案机关批准，项目资金来源为生产经营成本，出资比例100%，招标人为陕西延长石油（集团）有限责任公司炼化公司。本项目已具备招标条件，现招标方式为公开招标。\", \"type\": \"paragraph\"}, {\"t