NULL,NULL,NULL,NULL,'0866-26A3SXQY0860',NULL,NULL,'曹家滩煤矿南部风井场地矿井水处理站工程监理服务项目',NULL,'2026-09-02 00:00:00',NULL,NULL,'ACTIVE','APPROVED',NULL,'SOCIAL',0,NULL,'',NULL,NULL,NULL,'NONE',NULL,NULL,NULL,'NONE',NULL,NULL,'{}',NULL),(2097234065495326722,'','2026-09-10 09:34:56','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','聚烯烃弹性体（POR）工业化示范项目全厂安装工程招标公告','https://qyzb.shccmg.com/cms/default/webfile/1ywgg/20260901/1279496106006282240.html','59842f8357c1dc625e780d6824034a29eafed6a701e52ab2449393b1a049a8de',NULL,'HTML','<p class=\"p\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 16pt;\"><span style=\"font-family: 宋体;\">陕西陕煤协创达新材料有限公司</span></span></strong></p>\n<p class=\"p\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 16pt;\"><span style=\"font-family: 宋体;\">聚烯烃弹性体（</span>POR<span style=\"font-family: 宋体;\">）工业化示范项目</span><a name=\"OLE_LINK1\"></a></span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\">全厂安装工程</span></strong></p>\n<p class=\"p\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 16pt;\"><span style=\"font-family: 宋体;\">招标公告</span></span></strong></p>\n<p class=\"p\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 16pt;\"><span style=\"font-family: 宋体;\">招标编号：</span>0866-26B1SXQY0519</span></strong></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; tab-stops: left blank 21.3000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">项目所在地区：陕西省，渭南市</span></strong></p>\n<p class=\"18\" style=\"margin-left: 21.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">一</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">、招标条件</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">聚烯烃弹性体（</span><span style=\"font-family: 宋体;\">POR）工业化示范项目，招标人为陕西陕煤协创达新材料有限公司，招标项目资金来自企业自筹，出资比例为100%，资金已落实。招标机构为陕西秦源招标有限责任公司。项目已具备招标条件，现对该项目的全厂安装工程进行国内公开招标。</span></span></p>\n<p class=\"18\" style=\"margin-left: 21.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">二</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">、项目概况与招标范围</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&nbsp;</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.1、项目名称：</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">聚烯烃弹性体（</span><span style=\"font-family: 宋体;\">POR）工业化示范项目全厂安装工程</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（招标编号：</span><span style=\"font-family: 宋体;\">0866-26B1SXQY0519</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">）</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"19\" style=\"text-indent: 21.1pt;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">2.2、项目概况：</span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">聚烯烃弹性体（</span><span style=\"font-family: 宋体;\">POR）工业化示范项目占地约175.52亩，主要建设聚烯烃弹性体（POR)工业化示范目装置，聚合部分设置年产35000吨POR（干基）的生产线，可根据市场需求生产不同牌号产品，年操作时间按8000小时考虑，操作弹性50%~110%。主要包括公用工程服务设施生产办公室、库房、综合机修、循环水站、污水处理、全厂给排水、脱盐水系统、火炬及焚烧等和装置区的总体、原料卸料和中间罐、原料精制、催化剂及化学品配制、聚合脱气、汽提、溶剂回收及精制、后处理及干燥包装等工序单元以及配套的辅助工程、公用工程等设施。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.3、招标范围：</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 10.5000pt; mso-char-indent-count: 1.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">聚烯烃弹性体（</span><span style=\"font-family: 宋体;\">POR）工业化示范项目全厂安装工程：包含钢结构安装、设备安装、管道安装（含装置内给排水管道）、电仪安装、电信安装、防腐保温等，包含备品备件库、化学品库A、化学品库B、综合泵站、综合机修、危废暂存库、烷基铝库、脱盐水系统、换热站、门卫2及地磅房、消防及事故水池、雨水监控池、焚烧及热回收、火炬、全厂供电及外线、全厂工艺及供热外管、全厂电信、汽车衡、减温减压站、后处理及包装厂房、成品仓库、POR主装置（含主催化剂配置、压缩厂房、泵房、含镍废水处理设施、聚合脱气汽提框架、烷基铝配置、溶剂回收框架、液体罐区、废水池、装卸系统、泄压排放系统、冷冻单元、初期雨水池、室外设备区等）、控制室等，具体工作量以最终施工图纸为准。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.4、项目地点：</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕西省渭南市蒲城县</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">渭北煤化工业园区</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.5、工期：</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">240日历天（具体开工日期以招标人通知为准）。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.6、质量要求：</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">工程质量满足设计要求，符合国家及行业质量验收标准合格等级。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">三、投标人资格要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.1、资质要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）投标人须是中华人民共和国境内依法注册的独立法人或其他组织，企业法人应提供有效的营业执照，事业法人应提供事业单位法人证书，其他组织应提供合法登记证明文件；</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）投标人须具有有效的石油化工工程施工总承包二级及以上资质，具有有效的《安全生产许可证》；</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">3）投标人须具有有效的《特种设备生产许可证》，许可项目为压力管道安装GC1级和压力容器</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">安装</span><span style=\"font-family: 宋体;\">D级及以上</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.2、财务要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">投标人财务资质审查需提供的财务信息由以下两项任选其一：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）投标人须提供有效的基本账户银行出具的资信证明（投标截止日期前3个月内出具）及银行开户许可证（或银行基本账户证明资料）；</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）投标人需提供2023年&mdash;2025年连续三年经会计师事务所或审计机构出具的财务审计报告、财务报表复印件（至少包括审计报告签字盖章页、资产负债表、利润表、现金流量表）。投标人若成立不足三年，则提供自成立年份以来的财务审计报告、财务报表复印件。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.3、业绩要求</span></strong></p>\n<p class=\"19\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">投标人须提供近三年（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">自</span><span style=\"font-family: 宋体;\">2023年1月1日至投标截止日期</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">）至少</span><span style=\"font-family: 宋体;\">3份安装工程施工业绩，有效业绩以合同文件为准，合同文件须体现合同首页、主要工作范围页、合同签订时间页、双方盖章签字页</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\">等</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.4、人员要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）项目负责人（项目经理）：具备机电工程专业一级注册建造师资格及有效的安全生产考核合格证书（B证），且未担任其他在建设工程项目的项目经理或技术负责人（提供承诺书）。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）安全负责人：具备安全生产考核合格证书（C类）。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">以上人员须为本单位在册职工，提供由社会保障管理部门出具的有效社保证明材料</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2026</span><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: Times New Roman;\">1</span><span style=\"font-family: 宋体;\">月</span><span style=\"font-family: Times New Roman;\">1</span><span style=\"font-family: 宋体;\">日起</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">以后连续</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">3</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">个月）</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.5、信誉要求</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">（下列要求均由投标人提供加盖公章的承诺书）：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）投标人基本信息在&ldquo;陕西省建筑市场监管与诚信一体化管理系统&rdquo;可查询（提供截图）；。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）投标人未列入信用中国(https://www.creditchina.gov.cn/)严重失信主体名单。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">3）投标人未列入国家企业信用信息公示系统（https://www.gsxt.gov.cn/）严重违法失信名单（黑名单）。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.6、其他要求</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）单位负责人为同一人或者存在控股、管理关系的不同单位，不得同时参加本招标项目的投标；</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 24.1000pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）本次招标不接受联合体投标，资格审查方式为资格后审。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-top: 0.3000pt; margin-bottom: 3.0000pt; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">四、招标文件的获取</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">4.1</span></span></strong><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">获取时间：</span></span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">从</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2026</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">年</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">9</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">月</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">日</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">8</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">时</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">3</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">0</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">分至</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2026</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">年</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">9</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">月</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">7</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">日</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">18</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">时</span>00<span style=\"font-family: 宋体;\">分</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; vertical-align: baseline; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">4.2</span></span></strong><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">获取方式：</span></span></strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">凡有意参加投标者请在上述时间内登录</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&ldquo;秦源招标电子招标平台</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span>https://qyzb.shccmg.com/cms/default/webfile/index.html<span style=\"font-family: 宋体;\">）</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&rdquo;</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">下载招标文件，具体操作步骤如下：</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span>1<span style=\"font-family: 宋体;\">）登录</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&ldquo;秦源招标电子招标平台&rdquo;</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，按照提示信息进行投标人注册；</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span>2<span style=\"font-family: 宋体;\">）注册成功后，登录系统，在【我要参与】列表中找到所要参加的项目，点击【立即参与】</span><span style=\"font-family: Times New Roman;\">-</span><span style=\"font-family: 宋体;\">【确定】，获取投标资格。完成后在【我的项目】列表中找到已参与的项目，上传授权委托书、法定代表人及委托代理人身份证等资料，点击【提交】按系统提示下载招标文件，招标文件售价：</span><span style=\"font-family: Times New Roman;\">500</span><span style=\"font-family: 宋体;\">元</span><span style=\"font-family: Times New Roman;\">/</span><span style=\"font-family: 宋体;\">套，售后不退，项目结束后在秦源招标电子平台下载增值税电子普通发票</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span>3<span style=\"font-family: 宋体;\">）本项目采用全流程电子招标方式，潜在投标人须使用数字</span><span style=\"font-family: Times New Roman;\">CA</span><span style=\"font-family: 宋体;\">证书才能完成投标工作，数字</span><span style=\"font-family: Times New Roman;\">CA</span><span style=\"font-family: 宋体;\">证书办理及咨询电话：</span><span style=\"font-family: Times New Roman;\">4008206660</span><span style=\"font-family: 宋体;\">转</span><span style=\"font-family: Times New Roman;\">6</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span>4<span style=\"font-family: 宋体;\">）有关注册、下载招标文件；加密、上传电子申请文件等有关问题可咨询</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&ldquo;秦源招标电子招标平台&rdquo;</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">客服，客服电话：</span>400-685-1179<span style=\"font-family: 宋体;\">，邮箱：</span><span style=\"font-family: Times New Roman;\">qyebidding@163.com</span><span style=\"font-family: 宋体;\">。咨询日期：法定工作日，咨询时间：</span><span style=\"font-family: Times New Roman;\">08:30-12:00</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">，</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\">13:30-17:30<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">下载网址：</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: Times New Roman;\">1</span><span style=\"font-family: 宋体;\">）秦源招标二期电子招投标系统的投标人</span><span style=\"font-family: Times New Roman;\">/</span><span style=\"font-family: 宋体;\">投标人操作手册及开标注意事项</span><span style=\"font-family: Times New Roman;\">https://qyzb.shccmg.com/cms/default/webfile/cywj/20241202/1048174459543879680.html</span><span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: Times New Roman;\">2</span><span style=\"font-family: 宋体;\">）秦源招标二期投标客户端及驱动下载网址：</span><span style=\"font-family: Times New Roman;\">https://qyzb.shccmg.com/cms/default/webfile/cywj/20241126/1046075888694722560.html</span><span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-top: 0.3000pt; margin-bottom: 3.0000pt; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">五、投标文件的递交</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\">5.1<span style=\"font-family: 宋体;\">递交截止时间</span></span></strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">：</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2026</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">年</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">9</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">月</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">3</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">日</span>9<span style=\"font-family: 宋体;\">时整</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\">5.2<span style=\"font-family: 宋体;\">递交方式：</span></span></strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">电子文件上传递交到</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&ldquo;秦源招标电子招标平台&rdquo;</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，未在投标截止时间前成功递交的投标文件将被拒绝接</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">收</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"MsoBodyTextFirstIndent2\" style=\"margin-bottom: 0.0000pt; text-indent: 21.1000pt; line-height: 150%;\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">六、开标时间及地点</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\">6.1</span></strong><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">开标时间：</span></span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2026</span><span style=\"font-family: 宋体;\">年</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">9</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">月</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">3</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">日</span><span style=\"font-family: Times New Roman;\">9</span><span style=\"font-family: 宋体;\">时整</span></span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">；</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\">6.2<span style=\"font-family: 宋体;\">开标方式：</span></span></strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">开标通过</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&ldquo;</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">秦源招标电子招标平台</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&rdquo;</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">网上进行。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">七、其他</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">本项目招标公告在中国招标投标公共服务平台（</span><span style=\"font-family: 宋体;\">http://www.cebpubservice.com/）、陕西采购与招标公共服务平台（http://www.sntba.com/）和秦源招标电子招标平台（http://qyzb.shccmg.com/）发布。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">八、监督部门</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">本招标项目的监督部门：</span></span><a href=\"mailto:\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; line-height: 150%; color: #000000; mso-bidi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">陕西</span></span></a><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕煤</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">协创达新材料有限公司综合管理部</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">监督联系人：宋孝敏</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">监督电话：</span><span style=\"font-family: Times New Roman;\">18191709378</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">监督邮箱：</span><a href=\"mailto:songxm@pcccti.com\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; color: #000000; mso-bidi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: Times New Roman;\">songxm@pcccti.com</span></span></a></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">通讯地址：</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">陕西省渭南市蒲城县渭北煤化工业园区陕西陕煤协创达新材料有限公司综合办公室</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-top: 0.3000pt; margin-bottom: 3.0000pt; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">九、</span></span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">异议渠道及方式</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">投标人或其他利害关系人对本招标公告及招标文件内容有异议的，应在投标文件递交截止前</span><span style=\"font-family: Times New Roman;\">10</span><span style=\"font-family: 宋体;\">日内以书面形式</span><span style=\"font-family: Times New Roman;\">(</span><span style=\"font-family: 宋体;\">邮件发送</span><span style=\"font-family: Times New Roman;\">)</span><span style=\"font-family: 宋体;\">向招标人提出。提出的异议书应包含的内容：</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">1</span><span style=\"font-family: 宋体;\">）异议人的名称、地址、联系人及有效联系方式。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">2</span><span style=\"font-family: 宋体;\">）提出异议项目的名称、编号、所涉及的具体事项及被异议人的有效联系方式。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">3</span><span style=\"font-family: 宋体;\">）提出异议事项的基本事实、具体理由及明确诉求。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">4</span><span style=\"font-family: 宋体;\">）有效线索和相关证明材料。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">5</span><span style=\"font-family: 宋体;\">）异议人为其他利害关系人的，应提交利害关系证明。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-top: 0.3000pt; margin-bottom: 3.0000pt; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">十、</span></strong><strong><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">联系方式</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">招标人：陕西陕煤协创达新材料有限公司</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 18.35pt; line-height: 150%;\"><span style=\"font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">地址：陕西省渭南市蒲城县</span></span><span style=\"font-family: \'Times New Roman\'; l