INSERT INTO `bidding_notice_external` VALUES (2097235210846502914,'','2026-09-10 09:34:59','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕西陕煤曹家滩矿业有限公司曹家滩煤矿新建矿井水综合处置管线项目招标公告','https://qyzb.shccmg.com/cms/default/webfile/1ywgg/20260817/1274117742743519232.html','6fe1d0d8eb44204491864d6abbe7a046ae0a228832851d16a07352bd553481f3',NULL,'HTML','<h1 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; mso-pagination: none; text-align: center; line-height: 150%; mso-list: l2 level1 lfo2;\" align=\"center\"><a name=\"_Toc11334\"></a><strong><span style=\"font-family: 宋体; font-size: 22pt;\">&nbsp;招标公告</span></strong></h1>\n<p class=\"MsoNormal\" style=\"mso-pagination: widow-orphan; line-height: 150%;\"><a name=\"_Toc491883077\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">一、</span><span style=\"font-family: 宋体;\">招标条件</span></span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; mso-pagination: widow-orphan; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">本招标项目陕西陕煤曹家滩矿业有限公司曹家滩煤矿新建矿井水综合处置管线项目</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">，招标人为</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">陕西陕煤曹家滩矿业有限公司，招标项目资金来自企业自筹，出资比例为</span><span style=\"font-family: 宋体;\">100%。该项目已具备招标条件，陕西秦源招标有限责任公司受陕西陕煤曹家滩矿业有限公司的委托，现对</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">陕西陕煤曹家滩矿业有限公司曹家滩煤矿新建矿井水综合处置管线项目</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">进行（国内）公开招标。</span></p>\n<h2 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; layout-grid-mode: char; mso-pagination: none; vertical-align: baseline; line-height: 150%;\"><a name=\"_Toc491883078\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><a name=\"_Toc1268\"></a><a name=\"_Toc28119\"></a><a name=\"_Toc29247\"></a><span style=\"font-family: 宋体;\">二、</span><span style=\"font-family: 宋体;\">项目名称</span></span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">、</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">项目概况和</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">招标范围</span></strong></h2>\n<p class=\"MsoPlainText\" style=\"text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">2.1</span></strong><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">项目名称</span><span style=\"font-family: 宋体;\">:</span></span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">陕西陕煤曹家滩矿业有限公司曹家滩煤矿新建矿井水综合处置管线项目</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">招标编号：</span><span style=\"font-family: 宋体;\">0866-26A1SXQY0599</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">），本项目划分为</span><span style=\"font-family: 宋体;\">1个标段。</span></span></p>\n<p class=\"MsoBodyText\" style=\"margin-bottom: 0.0000pt; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><a name=\"_Toc491883079\"></a><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">2.2项目概况：</span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">本项目新建一条压力输水管道，位于陕煤运输专线道路北侧约</span><span style=\"font-family: 宋体;\">15.5m处，管道设计起点S1(X=4274815.251，Y=404314.780) </span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">接曹家滩煤矿</span><span style=\"font-family: 宋体;\">13盘区规划污水处理厂出水管</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，终点</span><span style=\"font-family: 宋体;\">S21(X=4273636.628, Y=407791.434)排入西尧则调蓄池。</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">新建输水管道管径</span><span style=\"font-family: 宋体;\">DN1200，总长 4453m，同时建设输水管道监测系统及附属设施。</span></span></p>\n<p class=\"MsoBodyText\" style=\"margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">设计主管道采用</span><span style=\"font-family: 宋体;\">&Phi;1220x12螺旋钢管，长度为4453m，沿线设置各种阀门井16座，排泥井5座，排泥</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">湿井</span><span style=\"font-family: 宋体;\">5座，配套设计输水管道监测系统。</span></span></p>\n<p class=\"MsoBodyText\" style=\"margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">顶管部分顶管采用</span><span style=\"font-family: 宋体;\">DN2200顶管专用钢筋混凝土（Ⅲ级）钢承口套管，内穿&Phi;1220x12螺旋钢管。除顶管段外，其余管道均采用开槽施工。</span></span></p>\n<p class=\"MsoBodyText\" style=\"margin-bottom: 0.0000pt; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">2.3</span></strong><strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">招标范围：</span></strong><span style=\"font-family: 宋体; font-size: 10.5pt;\">本次招标项目划分为一个标段</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoBodyText\" style=\"margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">新建输水管道管径为</span><span style=\"font-family: 宋体;\">DN1200，总长4453m，主要施工内容包括：按照设计要求采用&Phi;1220&times;12螺旋钢管敷设主管道，完成沿线各类井室（阀门井、排泥井、排泥湿井等）施工，开展DN2200钢筋混凝土顶管套管施工、管道监测系统安装调试，以及全部附属配套工程施工。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">具体</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">内容详见</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">招标文件</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">技术要求、施工图纸、工程量清单</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.4</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">工期：</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">合同生效后</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">12个月。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.5质量要求</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">符合现行国家有关工程施工质量验收规范、标准要求和设计要求，达到合格等级标准</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.6工程地点</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">：陕西省榆林市榆阳区孟家湾乡。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.7 质保期：自</span></strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">验收合格之日起</span><span style=\"font-family: 宋体;\">2年。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-right: -33.1500pt; vertical-align: baseline; line-height: 150%;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; mso-ansi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">三、投标人资格要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.1</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">资质要求：</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）投标人须是中华人民共和国境内依法注册的独立法人或其他组织，企业法人应提供有效的营业执照，事业法人应提供事业单位法人证书，其他组织应提供合法登记证明文件</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">）投标人必须具有</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">建筑行政主管部门颁发的市政公用工程施工总承包一级及以上资质，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">且具有有效的安全生产许可证。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2人员要求：</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%; mso-list: l1 level1 lfo3;\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">（1）</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">拟派</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">项目经理</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">：必须具有市政公用工程</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">一级</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">注册建造师资格证书（</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">须在本单位注册</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">和</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">有</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">效的《安全生产考核合格证书》（</span><span style=\"font-family: 宋体;\">B</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">证</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">），未担任其他在建工程项目负责人（提供</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">加盖单位公章的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">承诺书）【</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">提供上述证书的电子证书或扫描件均可</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">】，且须提供在本单位</span><span style=\"font-family: 宋体;\">2025年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">9</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">月</span><span style=\"font-family: 宋体;\">1日至投标截止日连续6个月由社会保障管理部门出具的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">本企业</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">有效社保证明材料；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">如项目经理注册证书出现以下情况，提供的项目经理一级注册建造师证书无效：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">1) 未在注册证书手写签名； </span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">2) 手写签名与电子签名图像笔迹不一致；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">3) 项目经理注册证书本人签署日期不是公告至投标的截止日期内的日期；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">4) 项目经理注册证书右上角无有效时限的水印。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">）拟派</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">技术</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">负责人：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">必须具有市政工程相关专业高级技术职称</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 0.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 0.0000pt;\">且</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">须提供在本单位</span><span style=\"font-family: 宋体;\">2025年9月1日至投标截止日连续6个月</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; mso-bidi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">由社会保障管理部门出具的有效社保证明材料</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; mso-bidi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.3财务要求：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">投标人须提供</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">近三年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">3</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">-2</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">02</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">5</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.4500pt; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">）经会计师事务所或审计机构出具的财务审计报告复印件（至少包括审计报告签字盖章页、资产负债表、利润表、现金流量表及财务报表附注）。投标人若成立不足三年，则提供自成立年份以来的财务审计报告复印件。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.4业绩要求：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">投标人必须提供（</span><span style=\"font-family: 宋体;\">2</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">022</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">1月1日至</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">投标截止日</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">）管道工程施工业绩</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">不少于</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">项</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">（证明文件以合同为准，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">合同有效日期以签订时间为准，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">合同复印件应清晰明了，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">合同内容需体现：合同首页、主要工作范围页、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">合同内容页、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">合同签订时间页、双方盖章签字页</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">3.5</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">信誉要求（以下提供加盖单位公章的承诺书）：</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）投标人未列入信用中国（https://www.creditchina.gov.cn/）严重失信主体名单；</span></span></p>\n<p class=\"MsoFooter\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: center blank 207.6500pt right blank 415.3000pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）投标人未列入国家企业信用信息公示系统（https://www.gsxt.gov.cn/）严重违法失信名单（黑名单）信息。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-right: -33.1500pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: baseline; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">3.</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">本项目</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">不</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">接受联合体投标。</span></p>\n<p class=\"MsoNormal\" style=\"margin-right: -33.1500pt; vertical-align: baseline; line-height: 150%;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; mso-ansi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">四、招标文件</span></strong><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; mso-ansi-font-weight: bold; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">获取</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">4.1、获取时间：202</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">18</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">时</span><span style=\"font-family: 宋体;\">00分至202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">24</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">日</span><span style=\"font-family: 宋体;\">18时00分（</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">法定节假日接受文件购买</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">）；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">4.2、获取方式：<