INSERT INTO `bidding_notice_external` VALUES (2097235454560731137,'','2026-09-10 09:34:59','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕煤电力信阳有限公司专职消防队外包项目招标公告','https://qyzb.shccmg.com/cms/default/webfile/1ywgg/20260811/1271871528320892928.html','37aa42358986c2fbb5d7b4d7dcd0339f990a3e0d81906219691d4d7b9865d331',NULL,'HTML','<p class=\"MsoNormal\" style=\"text-align: center; line-height: 150%; mso-outline-level: 1;\" align=\"center\"><a name=\"_Toc221201711\"></a><a name=\"_Toc231994623\"></a><a name=\"_Hlk221203643\"></a><a name=\"OLE_LINK13\"></a><a name=\"_Hlk169041017\"></a><strong><span style=\"line-height: 150%; font-family: 宋体;\">陕煤电力信阳有限公司</span></strong><strong><span style=\"line-height: 150%; font-family: 宋体;\">专职消防队外包</span></strong><strong><span style=\"line-height: 150%; font-family: 宋体;\">项目招标公告</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-align: center; line-height: 150%; mso-outline-level: 1;\" align=\"center\"><a name=\"_Toc221201712\"></a><a name=\"_Toc231994624\"></a><strong><span style=\"line-height: 150%; font-family: 宋体;\">（招标编号：<span lang=\"EN-US\">0866-26C3SXQY0558</span>）</span></strong></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%; mso-outline-level: 1;\"><a name=\"_Toc221201713\"></a><a name=\"_Toc231994625\"></a><strong><span style=\"line-height: 150%; font-family: 宋体;\">项目所在地区：河南省、信阳市、平桥区</span></strong></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">一、招标条件</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">本招标项目陕煤电力信阳有限公司专职消防队外包项目已由项目审批<span lang=\"EN-US\">/</span>核准<span lang=\"EN-US\">/</span>备案机关批准，项目业主为陕煤电力信阳有限公司，建设资金来自企业自筹，出资比例为<span lang=\"EN-US\">100%</span>，招标人为陕煤电力信阳有限公司。项目已具备招标条件，现对该项目进行公开招标。</span></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">二、<a name=\"_Hlk219386481\"></a>项目概况与招标范围</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">规模：<span lang=\"EN-US\">2.1</span>项目概况：陕煤电力信阳一、二期华豫电厂厂址位于信阳市平桥区，<span lang=\"EN-US\">4</span>台机组已正常投产。三期<span lang=\"EN-US\"> 2</span>&times;<span lang=\"EN-US\">1000MW </span>高效超超临界机组工程项目，厂址位于河南省信阳市平桥区五里店街道办事处凤台村内，距离现有一、二期华豫电厂约<span lang=\"EN-US\">18km</span>。该项目建设中<span lang=\"EN-US\">,</span>计划<span lang=\"EN-US\">2026</span>年投产。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">专职消防队外包服务工作包含一、二期运行机组和三期机组投产后及公用系统防火检查、动火监督、消防隐患排查、火灾扑救及消防器材的检查、补充、更换工作，消防车辆加油及日常维护保养<span lang=\"EN-US\">,</span>三期施工建设期间临建办公住宿区域、施工现场的消防救援，消防隐患排查<span lang=\"EN-US\">;</span>专职消防队接受招标人安排有关消防安全、抢险施救等临时性任务。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">2.2</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">招标项目名称：陕煤电力信阳有限公司专职消防队外包项目。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">2.3</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">招标范围：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><a name=\"OLE_LINK7\"></a><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">1</span>）承担招标人企业专职消防队的全部工作。负责专职消防队的队伍管理，组建一个符合专业要求的企业专职消防队，组织全队人员进行消防专业知识培训、灭火技能和体能训练，定期组织实施灭火作战演练，不断提高专职消防队防火业务水平和灭火作战能力。承担一、二期厂区和三期项目施工过程中和三期投产后厂区的消防执勤、灭火抢险、应急救援等消防相关工作，保持招标人消防队设施、装备、器材的良好状态，随时可以投入战斗。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">2</span>）协助招标人进行防火检查及消防辅助管理；对招标人的消防设施、器材的有效情况进行检查，确保消防设备处于完好状态，建立健全消防管理档案。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">3</span>）协助招标人对企业义务消防队员和职工进行消防培训和指导。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">4</span>）组建的专职消防队在接受电厂管理的同时，接受信阳市政府消防救援机构调度指挥，执行相应的灭火和抢险救灾任务<span lang=\"EN-US\">,</span>但出警时，必须第一时间向招标人报备。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 11.95pt; text-indent: 10.5pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">5</span>）熟悉掌握一、二期厂区和三期施工期间办公宿舍区域、施工现场和三期项目投产后整个厂区的建构筑物、设备名称位置、重点防火部位等。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">6</span>）进行消防巡查，纠正违章，做好巡查记录，将巡查结果及时向招标人归口主管部门汇报。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">7</span>）负责重点防火部位动火工作票安全措施的现场监护。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">8</span>）根据招标人安排，参加火灾类应急预案演练活动。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">9</span>）参与火灾事故调查。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">10</span>）消防车辆日常维护保养、加油，包含维护所需备品备件和耗材采购，不包括消防车辆大修。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">11</span>）消防器材的检查、卫生保洁，不合格消防器材的更换工作（招标人提供备品备件），消防器材检验时负责对器材进行回收及配置。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">12</span>）消防水系统不利点水压试验。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">13</span>）负责一、二期厂区的消防灭火救援工作；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">14</span>）三期项目建设期间的办公住宿区和施工现场消防救援，项目投产后三期厂区消防救援工作；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">15</span>）负责一、二期厂区和三期项目建设过程中和投产后厂区的消防问题隐患排查，建立消防隐患台账工作；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">16</span>）动火工作票的签发、对动火作业进行监护检查、可燃气体及可燃物浓度检测；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">17</span>）消防应急预案演练配合；以及其它紧急救援及配合工作等。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">18</span>）完成招标人交办的其他工作。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">详细要求详见招标文件第五章委托人要求。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">2.4</span><a name=\"_Hlk221528143\"></a><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">服务期限</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">：本合同服务期限自合同生效之日起三年。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">2.5</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">服务地点：</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">河南省信阳市平桥区陕煤电力信阳有限公司一、二期厂区及三期厂区。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">范围：本招标项目划分为<span lang=\"EN-US\">1</span>个标段，本次招标为其中的：（<span lang=\"EN-US\">001</span>）陕煤电力信阳有限公司专职消防队外包项目；</span></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">三、投标人资格要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><a name=\"OLE_LINK15\"></a><a name=\"_Hlk156767794\"></a><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">3.1</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">资质要求：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体;\">（<span lang=\"EN-US\">1</span>）投标人须是中国境内合法注册的独立法人或其他组织。企业法人应提供有效的营业执照，事业法人应提供事业单位法人证书，其他组织应提供合法登记证明文件；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><a name=\"OLE_LINK10\"></a><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体;\">（<span lang=\"EN-US\">2</span>）投标人须为已在国家消防救援局社会消防技术服务信息系统（</span><a title=\"autolink\" href=\"https://link.wtturl.cn/?target=https%3A%2F%2Fshhxf.119.gov.cn%2F&amp;scene=im&amp;aid=582478&amp;lang=zh\" target=\"_blank\" rel=\"noopener\"><span lang=\"EN-US\" style=\"color: windowtext; text-decoration: none; text-underline: none;\">https://shhxf.119.gov.cn/</span></a><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体;\">）完成从业信息录入公示的消防技术服务机构，须提供对应网页查询截图。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">3.2</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">业绩要求：<a name=\"_Hlk219452884\"></a>投标人须提供<span lang=\"EN-US\"> 2020</span>年<span lang=\"EN-US\">1</span>月<span lang=\"EN-US\">1</span>日至投标文件递交截止时间内消防技术服务业绩（消防设施检测、消防设施维护保养、消防安全评估业绩任一）或消防队外包服务业绩<span lang=\"EN-US\"> 2 </span>份，以上合同扫描件（合同扫描件须至少包含以下内容：合同封皮、合同双方盖章页、合同签订时间页及业绩要求对应的关键信息页）；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">3.3.</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">人员要求：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">3.3.1</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">专职消防队配置为队长、副队长各<span lang=\"EN-US\">1</span>人，指挥员<span lang=\"EN-US\">4</span>人，驾驶员<span lang=\"EN-US\">4</span>人，战斗员<span lang=\"EN-US\">12</span>名，共计<span lang=\"EN-US\">22</span>人。人力资源配置必须满足招标人技术规范服务要求，承担招标人企业专职消防队的全部工作。投标人按规范要求人数组建队伍，向招标人派谴的消防人员实行半军事化管理，要求人员年轻化、专业化。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">3.3.2</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">投标人应与用工人员签订劳动合同并购买符合国家有关规定的社保。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">3.3.3</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">专职消防队员应当具备下列条件： </span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">1</span>）具备良好的政治、业务素质和思想品德，身体健康，年龄范围在<span lang=\"EN-US\">18</span>周岁至<span lang=\"EN-US\">50</span>周岁，身高不低于<span lang=\"EN-US\">1.65</span>米的男性公民。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">2</span>）具有初中及以上文化程度。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">3</span>）专职消防队员年龄结构组成应满足：<span lang=\"EN-US\">18-30</span>岁不低于<span lang=\"EN-US\">50%</span>，<span lang=\"EN-US\">30-40</span>岁不低于<span lang=\"EN-US\">30%</span>，<span lang=\"EN-US\">40-50</span>岁不超过<span lang=\"EN-US\">20%</span>。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">4</span>）专职消防队要求至少<span lang=\"EN-US\">4</span>人取得消防设施操作员或消防员、注册消防工程师资质证书。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">投标人应在投标时对人员配置情况作出承诺，无需提供详细证明材料，具体人员配置情况及资格证明材料待入厂时提供。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">3.3.4</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">有下列情形之一的，不得担任专职消防队员：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">1</span>）受过刑事处罚的人员。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%;\" align=\"left\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">（<span lang=\"EN-US\">2</span>）曾被收容教育、强制隔离戒毒、劳动教养或者行政拘留的人员。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.6pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">3.4</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">信誉要求：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.6pt; line-height: 150%;\" align=\"left\"><a name=\"_Hlk231993094\"></a><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; letter-spacing: .05pt; mso-bidi-language: AR;\">3.4.1</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; letter-spacing: .05pt; mso-bidi-language: AR;\">投标人未列入信用中国（<span lang=\"EN-US\">https://www.creditchina.gov.cn/</span>）严重失信主体名单</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-ascii-font-family: \'Times New Roman\'; mso-hansi-font-family: \'Times New Roman\';\">（以投标人加盖公章的承诺书为准）</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; letter-spacing: .05pt; mso-bidi-language: AR;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.2pt; line-height: 150%;\" align=\"left\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; letter-spacing: .05pt; mso-bidi-language: AR;\">3.4.2</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; letter-spacing: .05pt; mso-bidi-language: AR;\">投标人未列入国家企业信用信息公示系统（<span lang=\"EN-US\">https://www.gsxt.gov.cn/</span>）严重违法失信名单（黑名单）信息</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-ascii-font-family: \'Times New Roman\'; mso-hansi-font-family: \'Times New Roman\';\">（以投标人加盖公章的承诺书为准）</span><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; letter-spacing: -.3pt; mso-bidi-language: EN-US; mso-bidi-font-weight: bold;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">3.5</span><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">其他要求：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 20.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体; letter-spacing: -0.25pt;\">本次招标不接受联合体投标。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.1pt; mso-char-indent-count: 2.0; line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">四、招标文件获取</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><a name=\"OLE_LINK6\"></a><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.1</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">获取时间：<span lang=\"EN-US\">2026</span>年<span lang=\"EN-US\">08</span>月<span lang=\"EN-US\">11</span>日上午<span lang=\"EN-US\">8</span>时<span lang=\"EN-US\">00</span>分至<span lang=\"EN-US\">2026</span>年<span lang=\"EN-US\">08</span>月<span lang=\"EN-US\">18</span>日下午<span lang=\"EN-US\">18</span>时<span lang=\"EN-US\">00</span>分（北京时间，下同）。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.2</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">获取办法：凡有意参加投标者，登录秦源招标电子招标平台（<span lang=\"EN-US\">qyzb.shccmg.com</span>），点击&ldquo;投标人登录&rdquo;请将法人授权委托书（附法定代表人、委托代理人身份证复印件）及上述&ldquo;<span lang=\"EN-US\">3.</span>投标人资格要求&rdquo;的<span lang=\"EN-US\">3.1-3.5</span>条相关资料以<span lang=\"EN-US\">PDF</span>格式上传，投标人即可办理缴费下载招标文件。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.3</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">未注册秦源招标电子招标平台的用户，登录秦源招标电子招标平台，点击&ldquo;投标人注册&rdquo;完善注册信息，具体操作参见秦源招标电子招标平台&mdash;客服中心&mdash;常用文件&mdash;手册及开标注意事项。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.4</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">投标人在秦源招标电子招标平台购买招标文件及缴费事宜。缴费完毕即可在平台下载招标文件。招标文件每套售价：<span lang=\"EN-US\">800</span>元，招标文件售后不退。购买招标文件发票可在平台开具后自行打印（仅提供电子增值税普通发票）</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.5</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">潜在投标人支付招标文件费用前需核对单位名称及开票信息，确认无误后支付费用，若单位名称及开票信息发生变化或填写有误，须先进行注册信息修改，修改内容审核通过后，再进行费用支付。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.6</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">已注册的潜在投标人若注册信息发生变更（如：与初始注册信息不一致），应及时网上提交变更申请。因未及时变更导致不利后果的，责任自负。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><a name=\"_Toc3620\"></a><a name=\"_Toc26117\"></a><a name=\"_Toc3809\"></a><a name=\"_Toc969735531\"></a><a name=\"_Toc31251\"></a><a name=\"_Toc2663\"></a><a name=\"_Toc16887\"></a><a name=\"_bookmark6\"></a><a name=\"_bookmark7\"></a><span class=\"NormalCharacter\"><span lang=\"EN-US\" style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">4.7</span></span><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">有关交易平台的业务咨询及技术支持请联系：</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><a name=\"_Toc8342\"></a><a name=\"_Toc1265555972\"></a><a name=\"_Toc17240\"></a><a name=\"_Toc10346\"></a><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">客服电话<span lang=\"EN-US\">: 400-685-1179</span>；邮箱<span lang=\"EN-US\">:qyebidding@163.com</span>；咨询日期<span lang=\"EN-US\">:</span>法定工作日；咨询时间<span lang=\"EN-US\">:08:30~12:00 13:30~17:30</span>。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; vertical-align: baseline;\" align=\"left\"><a name=\"_Toc3849\"></a><a name=\"_Toc1646337601\"></a><a name=\"_Toc26517\"></a><a name=\"_Toc20113\"></a><span class=\"NormalCharacter\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; mso-font-kerning: 0pt; mso-bidi-language: ZH-CN; mso-bidi-font-weight: bold;\">数字<span lang=\"EN-US\">CA</span>证书办理及咨询电话：<span lang=\"EN-US\">4008206660</span>转<span lang=\"EN-US\">6</span>，咨询时间：工作日及周末：<span lang=\"EN-US\">8:00-20:00</span>。</span></span></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">五、投标文件递交</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体;\">递交截止时间：<span lang=\"EN-US\">2026</span>年<span lang=\"EN-US\">09</span>月<span lang=\"EN-US\">03</span>日<span lang=\"EN-US\">09</span>时<span lang=\"EN-US\">00</span>分</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体;\">递交方式：投标人应在截止时间前须登录秦源招标电子招标平台递交投标文件</span></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">六、开标时间及地点</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体;\">开标时间：<span lang=\"EN-US\">2026</span>年<span lang=\"EN-US\">09</span>月<span lang=\"EN-US\">03</span>日<span lang=\"EN-US\">09</span>时<span lang=\"EN-US\">00</span>分</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span style=\"line-height: 150%; font-family: 宋体;\">开标地点：本项目采用网上开标，须登录秦源招标电子招标平台网上进行，投标人应提前<span lang=\"EN-US\">20</span>分钟登录秦源招标电子招标平台在线参与开标会议，按时完成解密和确认步骤。</span></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体;\">七、其它</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">7.1</span><span style=\"line-height: 150%; font-family: 宋体;\">本次招标公告同时在中国招标投标公共服务平台（<span lang=\"EN-US\">www.cebpubservice.com</span>）、陕西采购与招标网（<span lang=\"EN-US\">www.sntba.com</span>）、秦源招标电子招标平台（<span lang=\"EN-US\">qyzb.shccmg.com</span>）上发布；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">7.2</span><span style=\"line-height: 150%; font-family: 宋体;\">秦源招标电子招标平台的操作问题请咨询（业务咨询及技术支持客服电话：<span lang=\"EN-US\">400-685-1179,</span>邮箱：</span><span lang=\"EN-US\"><a href=\"mailto:qyebidding@163.com\"><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体; color: black; text-decoration: none; text-underline: none;\">qyebidding@163.com</span></a></span><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\"> ,</span><span style=\"line-height: 150%; font-family: 宋体;\">咨询时间：<span lang=\"EN-US\">08:30-12:00 13:30-17:30</span>）；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">7.3</span><span style=\"line-height: 150%; font-family: 宋体;\">秦源招标电子招标平台系统操作手册下载网址：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">https://qyzb.shccmg.com/cms/default/webfile/cywj/20241016/1031244793008619520.html</span><span style=\"line-height: 150%; font-family: 宋体;\">；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">7.4</span><span style=\"line-height: 150%; font-family: 宋体;\">投标人须办理数字<span lang=\"EN-US\">CA</span>证书并下载投标客户端。数字<span lang=\"EN-US\">CA</span>证书客服咨询电话：<span lang=\"EN-US\">4008206660</span>转<span lang=\"EN-US\">6</span>，咨询时间：工作日及周末：<span lang=\"EN-US\">8:00-20:00</span>）；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">7.5</span><span style=\"line-height: 150%; font-family: 宋体;\">秦源招标二期投标客户端及驱动下载网址：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0pt; mso-char-indent-count: 2.0; line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%; font-family: 宋体;\">https://qyzb.shccmg.com/cms/default/webfile/cywj/20241126/1046075888694722560.html</span></p>\n<p class=\"MsoNormal\" style=\"line-height: 150%;\" align=\"left\"><a name=\"_Hlk160634408\"></a><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: Tahoma; mso-font-kerning: 0pt;\">八、</span></strong><strong><span style=\"mso-bidi-font-size: 10.5pt; line-height: 150%; font-family: 宋体; mso-bidi-font-family: 宋体;\">监督部门及异议渠道和方式</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21pt; line-height: 150%; v