INSERT INTO `bidding_notice_external` VALUES (2097378112885100546,'','2026-09-10 09:35:02','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕煤集团神木柠条塔矿业有限公司  四平台、探亲楼换热站改造项目 招标公告','https://qyzb.shccmg.com/cms/default/webfile/1ywgg/20260716/1262492310948544512.html','2183222206de0a4f7bebd27f4af20076e744853e73da9198ef7f4261462d72c8',NULL,'HTML','<p class=\"18\" style=\"margin-right: 2.8500pt; margin-left: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><a name=\"_Toc16806\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\">陕煤集团神木柠条塔矿业有限公司</span></strong></p>\n<p class=\"18\" style=\"margin-right: 2.8500pt; margin-left: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\">&nbsp;<span style=\"font-family: 宋体;\">四平台、探亲楼换热站改造项目</span></span></strong></p>\n<p class=\"18\" style=\"margin-right: 2.8500pt; margin-left: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0.1pt; font-size: 16pt;\">招标公</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0.1pt; font-size: 16pt;\">告</span></strong></p>\n<p class=\"21\" style=\"margin-right: -11.0000pt; margin-left: 0.0000pt; mso-para-margin-right: -1.0000gd; mso-outline-level: 2; vertical-align: baseline; line-height: 150%;\"><a name=\"_Toc22253\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">一、招标条件</span></strong></p>\n<p class=\"MsoPlainText\" style=\"margin-right: -11pt; text-indent: 21pt; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">四平台、探亲楼换热站改造项目招标项目，招标人为陕煤集团神木柠条塔矿业有限公司，招标项目资金来自企业自筹，出资比例为</span><span style=\"font-family: 宋体;\">100%。该项目已具备招标条件，陕西秦源招标有限责任公司受陕煤集团神木柠条塔矿业有限公司的委托，现对四平台、探亲楼换热站改造项目进行国内公开招标。</span></span></p>\n<h2 style=\"margin-top: 0.0000pt; margin-right: -11.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: -1.0000gd; layout-grid-mode: char; mso-pagination: none; vertical-align: baseline; line-height: 150%;\"><a name=\"_Toc25190\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">二、项目概况、包次划分与招标范围</span></strong></h2>\n<p class=\"MsoNormal\" style=\"margin-right: -11.0000pt; mso-para-margin-right: -1.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: baseline; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">2.1</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">项目名称</span><span style=\"font-family: 宋体;\">:</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">&nbsp;<span style=\"font-family: 宋体;\">四平台、探亲楼换热站改造项目（</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">招标编号：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">0866-26E2SXQY0653），本项目划分为1个包次。</span></p>\n<p class=\"MsoNormal\" style=\"margin-right: -11.0000pt; mso-para-margin-right: -1.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: baseline; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">2.2招标概况：建设采暖高低区换热机组各一套、水处理系统一套、生活热水加热机组一套、 高低区供热水恒压机组各一套、电厂至四平台换热站换热机组一套、增压泵组一 套、换热站采暖和生活热水远程监测控制系统。 新建高、低区采暖机组各一套，水处理系统一套，高中低区生活热水机组各一套并增设远程监测控制系统；旧设备设施拆除，并对换热站重新布局，管道梳理</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-right: -11.0000pt; mso-para-margin-right: -1.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: baseline; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">2.3</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">招标范围：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">四平台换热站、探亲楼换热站整体改造工程，包含旧设备旧管路拆除清运、临时供热系统搭设、全套换热设备、水泵、水箱、阀门仪表、管材管件、</span><span style=\"font-family: 宋体;\">PLC 自控远程监控系统、运输、吊装、安装、管道焊接、保温防腐、水压冲洗、系统调试、72h 满负荷试运行、锅炉房集控室数据对接、人员培训、竣工资料等全部内容，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">详细工作内容及相关技术要求详见本招标文件五章</span><span style=\"font-family: 宋体;\">&ldquo;供货要求&rdquo;。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-right: -11.0000pt; mso-para-margin-right: -1.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: baseline; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">交货及安装期：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">合同生效后</span><span style=\"font-family: 宋体;\">60</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">个日历日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">完成安装</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin: 0pt; text-indent: 21pt; padding: 0pt; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">质保期：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 0.0000p