0,NULL,'',NULL,NULL,NULL,'NONE',NULL,NULL,NULL,'NONE',NULL,NULL,'{}',NULL),(2097379093173637121,'','2026-09-10 09:35:04','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','气体工厂捞渣机技改专用备件采购邀请公告','https://qyzb.shccmg.com/cms/default/webfile/2ywgg/20260820/1275133245012312064.html','6117dbfcb0568952feab9c935fe15f6a287599e0824dc9a855f5730b8cdadb3e',NULL,'HTML','<h1 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; mso-pagination: none; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\"><span style=\"font-family: 宋体;\">&nbsp;谈判采购邀请书</span></span></strong></h1>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><u><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;（被邀请单位）：</span></u><u></u></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕西秦源招标有限责任公司受陕煤集团榆林化学有限责任公司委托，就气体工厂捞渣机技改专用备件采购组织本次谈判，该项目已具备采购条件，现邀请贵公司参加该项目的谈判采购活动，相关事项告知如下：</span></p>\n<h2 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Cambria;\">1</span><span style=\"font-family: 宋体;\">、</span></span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购项目简介</span></strong></h2>\n<p class=\"MsoNormal\" style=\"text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.1</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购项目名称：气体工厂捞渣机技改专用备件采购</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（采购编号：</span><span style=\"font-family: 宋体;\">0866-26A2SXQY0846）</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.2采购人：陕煤集团榆林化学有限责任公司</span><u></u></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.3采购机构：</span><u><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕西秦源招标有限责任公司</span></u></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.4采购项目资金落实情况：</span><u><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">企业自筹，出资率</span><span style=\"font-family: 宋体;\">100%</span></span></u><u></u></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.5成交供应商数量及成交份额：</span><u><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">一家，成交份额</span><span style=\"font-family: 宋体;\">100%</span></span></u><u></u></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.6</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购项目</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">概况：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">现用</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">捞渣机</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">运行时</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">煤质灰分波动大，灰分含量增加时，粗渣产量大幅上升。大量粗渣超出捞渣机输送能力，导致捞渣机超电流运行，进而引发断链、跳停等设备故障，严重威胁生产安全。</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">需</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">对气化装置中捞渣机进行技改。改造内容（</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">）动力升级</span><span style=\"font-family: 宋体;\">:将电机功率由15kW提升至22kW，并配备相应的变频控制柜及电缆，增强设备动力输出。（</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">）链条更换</span><span style=\"font-family: 宋体;\">:把圆环链条替换为模锻链条，实现从点接触到面接触的转变，降低链环磨损，保障链条平稳运行。（</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">）轮系改造</span><span style=\"font-family: 宋体;\">:所有轮系按照模锻链条的适配形式进行改造，确保设备整体兼容性。（</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">4</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">）减速机适配</span><span style=\"font-family: 宋体;\">:根据新电机功率，更换相匹配的减速机，优化动力传输。（</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">5</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">）铸石板更换</span><span style=\"font-family: 宋体;\">:对斜坡段铸石板进行更换，减少灰渣输送阻力。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2、采购范围及相关要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 18.5500pt; mso-char-indent-count: 1.7700; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.1采购范围：本次拟采购</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">捞渣机</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">用</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">模锻刮板总成、模锻驱动装置总成、模假外置式内导轮总成、模锻半轴式托轮总成、模锻尾部张紧轮轴总成、模锻拖动机构总成、模锻回程托轮、模锻通轴式托轮总成、模锻压轮总成、新式模锻链条</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">和锌石板</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">详细采购范围和要求见谈判采购文件第五章采购需求。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 18.5500pt; mso-char-indent-count: 1.7700; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.2交货期：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2026年10月30日前</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 18.5500pt; mso-char-indent-count: 1.7700; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.3 交货地点</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">：陕西省榆林市神木市大保当镇榆神工业区清水工业园项目现场指定地点。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 18.5500pt; mso-char-indent-count: 1.7700; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.4</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">质保期</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">：货物交付开箱检验合格后</span><span style=\"font-family: 宋体;\">12个月。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">&nbsp;</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3、供应商资格要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.1供应商应依法设立且满足如下要求：</span></p>\n<p class=\"MsoFooter\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 10.5000pt; mso-char-indent-count: 1.0000; tab-stops: center blank 207.6500pt right blank 415.3000pt; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%; mso-list: l0 level1 lfo1;\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-size: 10.5pt;\">（1）</span><!--[endif]--><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">资质要求：</span><span style=\"font-family: 宋体;\">供应商必须</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">是</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">中国境内</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">依法</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">注册的独立法人或其他组织。企业法人应提供有效的营业执照，事业法人应提供事业单位法人证书，其他组织应提供合法登记证明文件；</span></p>\n<p class=\"MsoFooter\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 10.5000pt; mso-char-indent-count: 1.0000; tab-stops: center blank 207.6500pt right blank 415.3000pt; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">财务要求：</span></p>\n<p class=\"MsoFooter\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 10.5000pt; mso-char-indent-count: 1.0000; tab-stops: center blank 207.6500pt right blank 415.3000pt; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">供应商财务资质审查须提供的财务信息由以下两项任选其一：</span></p>\n<p class=\"MsoFooter\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 10.5000pt; mso-char-indent-count: 1.0000; tab-stops: center blank 207.6500pt right blank 415.3000pt; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">有效的基本账户银行出具的资信证明（谈判截止前三个月内）及银行开户许可证（或银行基本账户证明资料）；</span></p>\n<p class=\"MsoFooter\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 10.5000pt; mso-char-indent-count: 1.0000; tab-stops: center blank 207.6500pt right blank 415.3000pt; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">供应商须提供连续三年（</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">-202</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">5</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">年）经会计师事务所或审计机构出具的财务审计报告复印件（至少包括审计报告签字盖章页、资产负债表、利润表、现金流量表</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">及财务报表附注</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">）。供应商若成立不足三年，则提供自成立年份以来的财务审计报告表复印件。</span></p>\n<p class=\"MsoFooter\" style=\"mso-para-margin-left: 1.0000gd; tab-stops: center blank 207.6500pt right blank 415.3000pt; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">3）信誉要求（下列要求均由供应商提供加盖公章的承诺书）：</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 31.5000pt; mso-char-indent-count: 3.0000; mso-layout-grid-align: none; layout-grid-mode: char; text-autospace: ideograph-numeric; mso-pagination: widow-orphan; line-height: 23.0000pt; mso-line-height-rule: exactly;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">1）</span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">供应商未列入信用中国（</span><span style=\"font-family: 宋体;\">https://www.creditchina.gov.cn/）严重失信主体名单</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\">；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 31.5000pt; mso-char-indent-count: 3.0000; mso-layout-grid-align: none; layout-grid-mode: char; text-autospace: ideograph-numeric; mso-pagination: widow-orphan; line-height: 23.0000pt; mso-line-height-rule: exactly;\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">2）</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">供应商未</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">被</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">列入国家企业信用信息公示系统</span><span style=\"font-family: 宋体; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">https://www.gsxt.gov.cn/）</span></span><span style=\"font-family: 宋体; font-size: 10.5pt;\">严重违法失信名单</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">（</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">黑名单</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">）</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.2其他要求：</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%; mso-list: l1 level1 lfo2;\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-size: 10.5pt;\">（1）</span><!--[endif]--><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">法定代表人（单位负责人）</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">为同一人或者存在控股、管理关系的不同单位，不得同时参加本项目的</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">谈判；</span></p>\n<h2 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-weight: normal; font-size: 10.5pt;\">（</span><span style=\"font-family: 宋体; line-height: 150%; font-weight: normal; font-size: 10.5pt;\">2</span><span style=\"font-family: 宋体; line-height: 150%; font-weight: normal; font-size: 10.5pt;\">）本项目不接受联合体，资格审核方式为资格后审。</span></h2>\n<h2 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: Cambria;\">4</span><span style=\"font-family: 宋体;\">、采购文件的获取</span></span></strong></h2>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">4.1获取时间：202</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">20</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">时</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">00分</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">至</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">25</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">日</span><span style=\"font-family: 宋体;\">18时</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">00分（节假日接受文件购买）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">4.2获取方式：贵方请在上述时间内登录&ldquo;秦源招标电子招标平台（https://qyzb.shccmg.com/cms/default/webfile/index.html）&rdquo;确认并下载采购文件，具体操作步骤如下：</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）登录&ldquo;秦源招标电子招标平台&rdquo;，在【我的项目】列表中找到已参与的项目，点击【邀请回执】-进入邀请回执确认页面，上传附件，点击【发送】即可。随后按平台系统提示下载采购文件。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）谈判采购文件费用：500元，通过秦源招标电子招标平台支付，售后不退。（支付时请按平台要求提供单位信息及购买谈判采购文件的项目信息，注明采购编号及项目名称）。</span></span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 0.0000pt; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">3）有关注册、下载采购文件、上传电子响应文