INSERT INTO `bidding_notice_external` VALUES (2097379369309835265,'','2026-09-10 09:35:05','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕西煤业物资榆通有限责任公司小保当矿业公司1、2#副斜井加热设备与通风系统优化改造项目二次谈判采购公告','https://qyzb.shccmg.com/cms/default/webfile/2ywgg/20260807/1270440527287812096.html','da205aeb9cf682a7d32bfc6c146eca33a8ecccb521f505d97f45b254066d0260',NULL,'HTML','<h1 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-align: center; line-height: 150%;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\">二次</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\">谈判采购</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 16pt;\">公告</span></strong></h1>\n<p class=\"MsoNormal\" style=\"text-indent: 18.5500pt; mso-char-indent-count: 1.7700; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">陕西煤业物资榆通有限责任公司小保当矿业公司</span><span style=\"font-family: 宋体;\">1、2#副斜井加热设备与通风系统优化改造项目</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">项目，采购人为</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕西煤业物资榆通有限责任公司</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，项目资金来自企业自筹，出资比例为</span><span style=\"font-family: 宋体;\">100%。项目</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">已具备采购条件，陕西秦源招标有限责任公司受</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕西煤业物资榆通有限责任公司</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">的</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">委托，现公开邀请供应商参加</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">二次</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">谈判采购活动，</span> <span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">相关事项告知如下：</span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1、</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购项目简介</span></strong></h3>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.1采购项目名称：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">小保当矿业公司</span><span style=\"font-family: 宋体;\">1、2#副斜井加热设备与通风系统优化改造项目</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">（采购编</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">号：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">0866-26E2SXQY</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">0714</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">），本项</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">目共划分</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">个</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">包件</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.2采购人：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">陕西煤业物资榆通有限责任公司</span><u></u></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.3采购机构：陕西秦源招标有限责任公司</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.4采购项目资金落实情况：企业自筹，出资率100%</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1.5采购项目概况：陕西小保当矿业有限公司由于井下掘进面的延伸，矿井增大了进风量，加热设备使用时间较长，制热效果下降，现有设备无法满足井口进风加热需求，导致1、2#副斜井出现地面结冰现象，为满足井口通风加热需求及为以后的通风量增加余留富余量，需对1、2#副斜井6台加热机组进行改造更换，增加增压系统，确保井下安全生产。</span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2、</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购范围及相关要求</span></strong></h3>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: middle; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.1采购范围：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">供应商负责所供设备的设计、制造（含所需软件）、检验、试验、包装、运输（装卸）、随机标准附件、备品备件及专用工具、技术资料、安装、调试、试运转、人员培训与服务并配合完成整套设备性能考核验收、售后服务及质保期内的维修和保养等为实施本项目所需的全部工作内容，具体内容及要求详见谈判采购文件第五章采购需求</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.2交货期：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">签订合同后</span><span style=\"font-family: 宋体;\">60日历天完成交工</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.3交货地点：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">小保当</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">矿。</span></p>\n<p class=\"MsoBodyText\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.4质保期：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">设备投入使用并验收合格后</span><span style=\"font-family: 宋体;\">2年</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 24.1000pt; text-indent: -21.1000pt; mso-char-indent-count: -2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3、供应商资格要求</span></strong></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3.1</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商应满足如下要求：</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-size: 10.5pt;\">（1）</span><!--[endif]--><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">依法设立</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">：</span></strong></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l1 level1 lfo2;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-size: 10.5000pt;\">a.</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">必须具有独立法人资</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">格的通风加热机组的生产厂家或授权代理商，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">并提供加载统一社会信用代码的营业执照或事业单位法人证书、提供开户许可证或基本存款账户信息证明材料。</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l1 level1 lfo2;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-size: 10.5000pt;\">b.</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">供应商</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">为授权代理商的，必须提供通风加热机组的生产厂家针对本项目的唯一授权委托书；（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">一个制造商对同一品牌同一型号的货物，仅能委托一个代理商参加</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">，且生产厂家与授权代理商不得同时参加</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">谈判采购</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">）。</span></p>\n<p class=\"16\" style=\"mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1; margin: 0.0000pt;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-variant: normal; font-size: 10.5pt;\">（2）</span><!--[endif]--><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">资质要求：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">必须具备矿山工程施工总承包一级及以上资质，同时具备有效的安全生产许可证。</span></p>\n<p class=\"16\" style=\"mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1; margin: 0.0000pt;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-weight: bold; font-size: 10.5000pt;\">（3）</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">项目负责人要求：拟派项目负责人须具备机电工程专业二级及以上注册建造师资格，并具有有效的安全生产考核合格证书（</span><span style=\"font-family: 宋体;\">B证），同时提供2025年10月以后连续6个月的个人社保缴纳证明复印件并加盖公章，另需要提供项目负责人无在建项目承诺书。</span></span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">4</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">财务要求：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">必须提供（</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">3</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">-202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">5</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">年）连续三年经第三方审计的财务报告，若公司成立时间不足三年，可提供成立之后年份经第三方审计的财务报告。</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">5</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">业绩要求：</span></strong></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">a.如为生产厂家参与，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">应具有近年（自</span><span style=\"font-family: 宋体;\">2023年1月1日至投标截止日期）至少</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">项</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">同类项目</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">业绩（业绩以合同及合同对应的任意一张增值税发票为准，对应的增值税发票在国家税务总局全国增值税发票查验平台核验必须真实、有效，合同必须有双方盖章页、首页、供货清单，合同内容清晰，甲乙双方盖章完整，有效业绩时间以合同签订时间为准）。</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">b.如为授权代理商参与，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">应具有近年（自</span><span style=\"font-family: 宋体;\">2023年1月1日至投标截止日期）至少</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">项</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">同类项目</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">业绩（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">业绩提供生产厂家销售业绩或授权代理商自身销售业绩均可，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">业绩以合同及合同对应的任意一张增值税发票为准，对应的增值税发票在国家税务总局全国增值税发票查验平台核验必须真实、有效，合同必须有双方盖章页、首页、供货清单，合同内容清晰，甲乙双方盖章完整，有效业绩时间以合同签订时间为准）。</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">6</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">信誉要求：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">a.未列入信用中国（https://www.creditchina.gov.cn/)严重失信主体名单。</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">b.未列入国家企业信用信息公示系统（https://www.gsxt.gov.cn/)严重违法失信名单（黑名单）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">。</span></p>\n<p class=\"16\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">7</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">其他要求：</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">a.法定代表人为同一个人的两个及两个以上法人，母公司、全资子公司及其控股公司，都不得同时参与谈判采购。b.</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">供应商及项目负责人基本信息应在</span><span style=\"font-family: 宋体;\">&ldquo;陕西省(或全国)建筑市场监管公共服务平台&rdquo;可查询</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">。</span></p>\n<p class=\"16\" style=\"margin-top: 0pt; margin-right: 0pt; margin-bottom: 0pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3.2</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商不得存在下列情形之一：（提供承诺书或相关证明材料）</span></p>\n<p class=\"16\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">处于被责令停产停业、暂扣或者吊销执照、暂扣或者吊销许可证、吊销资质证书状态；进入清算程序，或被宣告破产，或其他丧失履约能力的情形；</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: Times New Roman;\">.3</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: \'Times New Roman\'; mso-hansi-font-family: \'Times New Roman\'; mso-bidi-font-family: \'Times New Roman\'; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">本次采购接受联合体，联合体参与时必须提供联合体协议书，联合体成员不得超过</span><span style=\"font-family: Times New Roman;\">2</span><span style=\"font-family: 宋体;\">家，联合体牵头单位为通风加热机组的生产厂家或授权代理商。</span></span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">4、采购文件的获取</span></strong></h3>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">4.1如贵单位有意参加</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">谈判</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">采购活动，请于</span><span style=\"font-family: 宋体;\">2026年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">日上午</span><span style=\"font-family: 宋体;\">8时至2026年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">13</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">下午</span><span style=\"font-family: 宋体;\">18时内登录&ldquo;秦源招标电子招标平台&rdquo;网址为：（http://qyzb.shccmg.com/）下载</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">谈判采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">文件，具体操作步骤如下：</span></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）登录&ldquo;秦源招标电子招标平台&rdquo;，按照提示信息进行供应商注册；</span></span></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）注册成功后，登录系统，在【我要参与】列表中找到所要参加的项目，点击【立即参与】-【确定】，获取参与资格。完成后在【我的项目】列表中找到已参与的项目，上传授权委托书及&ldquo;三、供应商资格要求&rdquo;所有资料的扫描件，点击【提交】。</span></span></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">3）有关注册、下载</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">谈判</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">采购文件、上传电子文件等有关问题可咨询</span><span style=\"font-family: 宋体;\">&ldquo;秦源招标电子招标平台&rdquo;客服，客服电话：400-685-1179，邮箱：qyebidding@163.com。咨询日期：法定工作日，咨询时间：08:30-12:00，13：30-17:30。</span></span></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">秦源招标二期电子招标系统的供应商</span><span style=\"font-family: 宋体;\">/供应商操作手册及</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">谈判采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">注意事项：</span><span style=\"font-family: 宋体;\">https://qyzb.shccmg.com/cms/default/webfile/cywj/20241202/1048174459543879680.html。</span></span></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">4.2</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">谈判</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">采购文件费用：</span><span style=\"font-family: 宋体;\">500元，通过秦源招标电子招标平台支付，售后不退。</span></span></p>\n<p class=\"17\" style=\"mso-para-margin-top: 0.0000gd; mso-para-margin-bottom: 0.0000gd; text-indent: 21.0000pt;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4.3购买</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">谈判</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">采购文件的发票，待采购机构开出后，供应商可在平台打印（购买</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">谈判</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">采购文件发票仅提供电子增值税普通发票）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt;\">。</span></p>\n<p class=\"17\" style=\"mso-para-margin-top: 0.0000gd; mso-para-margin-bottom: 0.0000gd; text-indent: 21.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt;\">4.5采购文件获取不足</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt;\">两</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-bidi-font-family: \'Times New Roman\'; font-size: 10.5000pt;\">家时，本次采购活动终止。</span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">5、响应文件的递交</span></strong></h3>\n<p class=\"MsoNormal\" style=\"text-indent: 15.7500pt; mso-char-indent-count: 1.5000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">5.1响应文件递交的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">截止时间为</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">17</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">上午</span><span style=\"font-family: 宋体;\">09时整（北京时间）。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 15.7500pt; mso-char-indent-count: 1.5000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">5.2递交方式：电子文件上传递交到&ldquo;秦源招标电子招标平台&rdquo;，未在谈判开始时间前成功递交的响应文件将被拒绝接受。</span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">6、谈判时间和地点</span></strong></h3>\n<p class=\"MsoNormal\" style=\"text-indent: 15.7500pt; mso-char-indent-count: 1.5000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">6.1谈判开始时间：202</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">6</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">年</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">17</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">上午</span><span style=\"font-family: 宋体;\">9:00（北京时间）。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 15.7500pt; mso-char-indent-count: 1.5000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">6.2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">谈判</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">方式：本次谈判通过</span><span style=\"font-family: 宋体;\">&ldquo;秦源招标电子招标平台&rdquo;网上进行。</span></span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">7、发布公告的媒介</span></strong></h3>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; page-break-after: avoid; mso-pagination: widow-orphan; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-weight: normal; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">本谈判采购公告在中国招标投标公共服务平台（</span><span style=\"font-family: 宋体;\">http://www.cebpubservice.com/）、陕西采购与招标网（http://www.sntba.com）及秦源招标电子招标平台（http://qyzb.shccmg.com）上同时发布。</span></span></h3>\n<p class=\"18\" style=\"mso-para-margin-left: 0.0000gd; text-indent: 0.0000pt; mso-char-indent-count: 0.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; mso-outline-level: 2; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">8、</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">监督部门及异议渠道和方式</span></strong></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">8</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">.1本项目监督部门：陕西煤业物资榆通有限责任公司物资管理部。</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">联系人：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">杨</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">先生；监督电话：</span><span style=\"font-family: 宋体;\">13891246218；监督邮箱：wgb@smwzyt.com。</span></span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">8.2 异议渠道及方式:</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">供应商</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">或其他利害关系人对本</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">谈判采购</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">公告及</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">谈判采购文件</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">内容有异议的，应在</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">谈判采购文件</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">递交截</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">止前</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">5</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">日</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">内以书面形式</span><span style=\"font-family: 宋体;\">(邮件发送)向</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">人提出，邮箱：</span><span style=\"font-family: 宋体;\">wgb@smwzyt.com。</span></span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">提出的异议书应包含的内容：</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1)异议提出人名称、地址、电话等；</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2)具体的异议事项、事实依据及相关证明材料；</span></p>\n<p class=\"20\"