INSERT INTO `bidding_notice_external` VALUES (2097379785388986369,'','2026-09-10 09:35:06','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕西煤业物资榆通有限责任公司柠条塔矿井下主要加压泵房变频器及控制系统更新（控制）项目采购二次询比采购公告','https://qyzb.shccmg.com/cms/default/webfile/2ywgg/20260729/1267222613306900480.html','72f3bceca4c48a7a7882f2af1bc7d17536a9492762a9e8a584f68067ef0a3202',NULL,'HTML','<p class=\"16\" style=\"text-indent: 0.0000pt; text-autospace: ideograph-numeric; page-break-after: avoid; mso-pagination: lines-together; text-align: center; line-height: 150%; margin: 0.0000pt;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 18pt;\">二次</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 18pt;\">询比采购公告</span></strong></p>\n<p class=\"19\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">柠条塔矿井下主要加压泵房变频器及控制系统更新（控制）项目采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，采购人为陕西煤业物资榆通有限责任公司，项目资金来自企业自筹，出资比例为</span><span style=\"font-family: 宋体;\">100%。项目</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">已</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">具备采购条件，陕西秦源招标有限责任公司受陕西煤业物资榆通有限责任公司委托，现公开邀请供应商参加</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">二次</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购活动，相关事项告知如下：</span><u></u></p>\n<p class=\"19\" style=\"margin: 0pt; text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">1</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购项目简介</span></strong></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 452.4000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">1.1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">采购项目名称：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">柠条塔矿井下主要加压泵房变频器及控制系统更新（控制）项目采购（采</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">购编号：</span><span style=\"font-family: 宋体;\">0866-26E2SXQY0664）</span></span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 452.4000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">1.2</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">釆购人：陕西煤业物资榆通有限责任公司</span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 452.4000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">1.3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">釆</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">机构：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">陕西秦源招标有限责任公司</span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 452.4000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1.4</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">釆购项目资金落实情况：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">企业自筹，比例</span><span style=\"font-family: 宋体;\">100%</span></span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 452.4000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1.5</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">采购项目概况：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">本项目为陕煤集团神木柠条塔矿业井下主要加压泵房控制系统更新改造项目，适配井下含瓦斯、煤尘的爆炸性环境。项目对三处井下恒压供水泵房开展自动化升级，采购</span><span style=\"font-family: 宋体;\">PLC控制箱、防爆电源、各类矿用传感器、电动阀门、摄像仪及配套线缆辅材，定制开发排水集控系统软件。改造后系统具备就地、自动、远程、检修四种控制模式，可实现恒压供水、水泵轮换、故障保护、视频联动及数据联网上传，达成泵房无人值守智能管控。</span></span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 452.4000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; mso-outline-level: 3; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">.</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6成交供应商数量及成交份额：一家，100%</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"> <span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"19\" style=\"margin: 0pt; text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购范围及相关要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.1采</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">购范围：矿用隔爆兼本安型可编程控制</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">箱</span><span style=\"font-family: 宋体;\">3套，矿用隔爆兼本安型锂离子蓄电池电源、</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">矿用本安型操作台、煤矿供排水监控系统软件</span><span style=\"font-family: 宋体;\">1套、传感器一批、控制电缆及软件等。供货范围包含设备供货、系统设计、制造（含所需软件）、检验、试验、包装、运输（装卸）、随机标准附件、备品备件及专用工具、技术资料、现场安装指导、调试、试运转、人员培训及系统联网接入服务，与服务并配合完成整套设备性能考核验收、售后服务及质保期内的维修和保养等为实施本项目所需的全部工作内容，具体内容及要求详见招标文件第五章供货要求。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.2</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">交货期：合同签订</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">生效</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">后</span><span style=\"font-family: 宋体;\">40个工作日内到矿</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.3</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">交货地点：</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">柠条塔煤矿</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.4质保期：运行12个月或验收通过后18个月。</span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc219\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商资格要求</span></strong></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3.1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商应满足如下要求：</span></p>\n<p class=\"21\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 46.3000pt left blank 446.5000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-size: 10.5pt;\">（1）</span><!--[endif]--><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">依法设立</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">必须是在中华人民共和国境内注册的独立法人</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">的矿用隔爆兼本安型可编程控制箱、煤矿排水监控系统、矿用本安型操作台生产厂家，</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">具备有效的企业法人营业执照</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">，提供开户许可证或基本存款账户信息证明材料</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"21\" style=\"mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 46.3000pt left blank 446.5000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1; margin: 0.0000pt;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-variant: normal; font-size: 10.5pt;\">（2）</span><!--[endif]--><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">资质要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">需提供煤矿排水监控系统</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">煤矿安全标志证书。</span></p>\n<p class=\"21\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 46.3000pt left blank 446.7000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">财务要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">必须提供（</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">-202</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">5</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">年）连续三年经第三方审计的财务报告，若公司成立时间不足三年，可提供成立之后年份经第三方审计的财务报告。</span></p>\n<p class=\"21\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 46.3000pt left blank 156.3000pt left lined 446.5000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">业绩要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">应具有近年（自</span><span style=\"font-family: 宋体;\">2023年1月1日至</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">截止日期）至少三项</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">排水控制系统</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">销售</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">业绩（业绩以合同及合同对应的任意一张增值税发票为准，对应的增值税发票在国家税务总局全国增值税发票查验平台核验必须真实、有效，合同必须有双方盖章页、首页、供货清单，合同内容清晰，甲乙双方盖章完整，有效业绩时间以合同签订时间为准）。</span></p>\n<p class=\"21\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 46.3000pt left blank 446.5000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">5</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">信誉要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">未被国家企业信用信息公示系统（</span><span style=\"font-family: 宋体;\">http://www.gsxt.gov.cn/index.html）列入严重违法失信名单（黑名单）</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">；未被列入</span><span style=\"font-family: 宋体;\">&ldquo;信用中国&rdquo;（http://www.creditchina.gov.cn/）严重失信主体名单。</span></span></p>\n<p class=\"21\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 46.3000pt left blank 446.5000pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">其他要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">法定代表人为同一个人的两个及两个以上法人，母公司、全资子公司及其控股公司，都不得同时</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">参加</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"21\" style=\"margin-top: 0pt; margin-right: 0pt; margin-bottom: 0pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3.2</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商不得存在下列情形之一：（提供承诺书或相关证明材料）</span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">处于被责令停产停业、暂扣或者吊销执照、暂扣或者吊销许可证、吊销资质证书状态；进入清算程序，或被宣告破产，或其他丧失履约能力的情形；</span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">.3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">本次采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">不接受</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">联合体。</span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc25004\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">4</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购文件的获取</span></strong></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4.1如贵单位有意参加参加询比采购活动，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">请于</span><span style=\"font-family: 宋体;\">2026年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">7</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">30</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">日上午</span><span style=\"font-family: 宋体;\">8时至2026年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">4</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">日下</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">午</span><span style=\"font-family: 宋体;\">18时内登录&ldquo;秦源招标电子招标平台&rdquo;网址为：（http://qyzb.shccmg.com/）下载询比采购文件，具体操作步骤如下：</span></span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）登录&ldquo;秦源招标电子招标平台&rdquo;，按照提示信息进行供应商注册；</span></span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">2）注册成功后，登录系统，在【我要参与】列表中找到所要参加的项目，点击【立即参与】-【确定】，获取参与资格。完成后在【我的项目】列表中找到已参与的项目，上传授权委托书及&ldquo;三、供应商资格要求&rdquo;所有资料的扫描件，点击【提交】。</span></span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">3）有关注册、下载询比采购文件、上传电子文件等有关问题可咨询&ldquo;秦源招标电子招标平台&rdquo;客服，客服电话：400-685-1179，邮箱：qyebidding@163.com。咨询日期：法定工作日，咨询时间：08:30-12:00，13：30-17:30。</span></span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">秦源招标二期电子招标系统的供应商</span><span style=\"font-family: 宋体;\">/供应商操作手册及</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">注意事项：</span><span style=\"font-family: 宋体;\">https://qyzb.shccmg.com/cms/default/webfile/cywj/20241202/1048174459543879680.html。</span></span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4.2询比采购文件费用：500元，通过秦源招标电子招标平台支付，售后不退。</span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4.3购买询比采购文件的发票，待采购机构开出后，供应商可在平台打印（购买询比采购文件发票仅提供电子增值税普通发票）。</span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4.4询比采购文件获取不足三家时，本次采购活动终止，采购人重新组织采购。</span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc16929\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">5</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">响应文件的递交</span></strong></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">5.1递交截止时间</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">：</span><span style=\"font-family: 宋体;\">2026年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">11</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">日上午</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">9:00（北京时间）。</span></p>\n<p class=\"21\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">5.2递交方式：将电子文件上传递交至&ldquo;秦源招标电子招标平台&rdquo;，未在询比开始时间前成功递交的响应文件将被拒绝接收。</span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc28407\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">6</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比时间和地点</span></strong></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 42.2500pt left blank 108.5000pt left blank 168.5000pt left blank 229.7000pt left blank 276.9500pt left blank 290.6500pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6.1询比开始</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">时间：</span><span style=\"font-family: 宋体;\">2026年</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">8</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">月</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\">11</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; mso-font-width: 100%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">日上午</span><span style=\"font-family: 宋体;\">9:00（</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">北京时间）。</span></p>\n<p class=\"21\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; tab-stops: left blank 42.2500pt left blank 108.5000pt left blank 168.5000pt left blank 229.7000pt left blank 276.9500pt left blank 290.6500pt; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6.2询比地点：秦源招标电子招标平台。</span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc14598\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-variant: normal; font-size: 10.5pt;\">7.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">发布公告的媒介</span></strong></p>\n<p class=\"18\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">本询比采购公告在中国招标</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">投标</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">公共服务平台（</span><span style=\"font-family: 宋体;\">http://www.cebpubservice.com/）、陕西采购与招标网（http://www.sntba.com）及秦源招标电子招标平台（http://qyzb.shccmg.com）上同时发布。</span></span></p>\n<p class=\"18\" style=\"text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; mso-outline-level: 2; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">8.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">监督部门及异议渠道和方式</span></strong></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">8</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.1本项目监督部门:陕西煤业物资榆通有限责任公司物资管理部。</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">联系人：</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">杨</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">先生；监督电话：</span><span style=\"font-family: 宋体;\">13891246218；监督邮箱：wgb@smwzyt.com。</span></span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">8.2 异议渠道及方式:</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">或其他利害关系人对本</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">公告及</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">文件内容有异议的，应在</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">文件递交截止前</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">5</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">日内以书面形式</span><span style=\"font-family: 宋体;\">(邮件发送)向</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">人提出，邮箱：</span><span style=\"font-family: 宋体;\">wgb@smwzyt.com。</span></span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">提出的异议书应包含的内容：</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">1)异议提出人名称、地址、电话等；</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2)具体的异议事项、事实依据及相关证明材料；</span></p>\n<p class=\"20\" style=\"margin-left: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; word-break: break-all; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3)异议人署名。异议人为自然人的，由本人签字；异议人为法人或者其他组织的，由法定代表人或者主要负责人签字并加盖公章；</span></p>\n<p class=\"18\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><s