blank 414.0000pt left blank 450.0000pt; mso-layout-grid-align: none; layout-grid-mode: char; word-break: break-all; punctuation-trim: leading; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">电子邮箱：</span><span style=\"font-family: 宋体;\">sxqygjb@126.com</span></span></p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0866-26D1SXQY0285',NULL,NULL,'陕煤金融中心(二期)DK56四网及全信号覆盖工程','陕西天工建设有限公司','2026-07-22 00:00:00',NULL,NULL,'ACTIVE','APPROVED',NULL,'SOCIAL',0,NULL,'',NULL,NULL,NULL,'NONE',NULL,NULL,NULL,'NONE',NULL,NULL,'{}',NULL),(2097379930331549697,'','2026-09-10 09:35:06','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕西煤业物资榆通有限责任公司小保当矿矿用摊铺机询比采购公告','https://qyzb.shccmg.com/cms/default/webfile/2ywgg/20260721/1264319611864612864.html','0ae7323f05e04c5c203641173fecae5e1148c3ce898176abdfa3302bbe3f5743',NULL,'HTML','<p class=\"18\" style=\"text-indent: 0.0000pt; text-autospace: ideograph-numeric; page-break-after: avoid; mso-pagination: lines-together; text-align: center; line-height: 150%; margin: 0.0000pt;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 18pt;\">二次</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 18pt;\">询比采购公告</span></strong></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">小保当矿矿用摊铺机询比采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，采购人为陕西煤业物资榆通有限责任公司，项目资金来自企业自筹，出资比例为</span><span style=\"font-family: 宋体;\">100%。项目</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">已</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">具备采购条件，陕西秦源招标有限责任公司受陕西煤业物资榆通有限责任公司委托，现公开邀请供应商参加</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">二次</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购活动，相关事项告知如下：</span><u></u></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">1</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购项目简介</span></strong></p>\n<p class=\"20\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">1.1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">采购项目名称：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">小保当矿矿用摊铺机询比采购（采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">编号：</span><span style=\"font-family: 宋体;\">0866-26E2SXQY0587）</span></span></p>\n<p class=\"20\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">1.2</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">釆购人：陕西煤业物资榆通有限责任公司</span></p>\n<p class=\"20\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">1.3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">釆</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">机构：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">陕西秦源招标有限责任公司</span></p>\n<p class=\"20\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1.4</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">釆购项目资金落实情况：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">企业自筹，比例</span><span style=\"font-family: 宋体;\">100%</span></span></p>\n<p class=\"20\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1.5</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">采购项目概况：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">本项目为</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">小保当</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">一号煤矿矿用混凝土摊铺机采购项目，需采购</span><span style=\"font-family: 宋体;\">1台符合煤矿防爆标准的混凝土摊铺机，设备需适配矿区高湿、多粉尘、存在瓦斯及煤尘爆炸风险的井下工况，海拔适配1200m作业环境。设备最大摊铺宽度3500mm、厚度350mm，搭载防爆柴油机，具备无级调速、自动找平、远程遥控、瓦斯监测停机及环境监控等智能化功能。</span></span></p>\n<p class=\"20\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; mso-outline-level: 3; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">.</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6成交供应商数量及成交份额：一家，100%</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购范围及相关要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.1采</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">购范围：</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">负责所供设备的设计、制造（含所需软件）、检验、试验、包装、运输（装卸）、随机标准附件、备品备件及专用工具、技术资料、安装、调试、试运转、人员培训与服务并配合完成整套设备性能考核验收、售后服务及质保期内的维修和保养等为实施本项目所需的全部工作内容，具体内容及要求详见</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">文件第五章</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购需求</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.2</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">交货期：合同签订</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">生效</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">后</span><span style=\"font-family: 宋体;\">60天内</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.3</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">交货地点：</span><span style=\"font-family: \'Times New Roman\'; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">小保当</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">一号煤矿</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.4质保期：产品投入使用12个月或到货验收18个月，以先到为准。</span></p>\n<p class=\"16\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc219\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商资格要求</span></strong></p>\n<p class=\"20\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3.1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商应满足如下要求：</span></p>\n<p class=\"20\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-size: 10.5pt;\">（1）</span><!--[endif]--><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">依法设立</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">必须具有独立法人资格的生产厂家，并提供加载统一社会信用代码的营业执照或事业单位法人证书。</span></p>\n<p class=\"20\" style=\"mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1; margin: 0.0000pt;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">（2）</span><!--[endif]--><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">资质要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">必须提供</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">整机</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;