pt solid #000000; mso-border-right-alt: 0.5000pt solid #000000; border-top: none; mso-border-top-alt: 0.5000pt solid #000000; border-bottom: 1.0000pt solid #000000; mso-border-bottom-alt: 0.5000pt solid #000000;\" valign=\"center\" width=\"196\">\n<p class=\"MsoNormal\" style=\"mso-pagination: widow-orphan; text-align: center; vertical-align: middle; line-height: 150%; margin: 0.0000pt;\" align=\"center\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">110kV变电站故障录波、小电流接地选线装置及GIS综合在线监测系统</span></p>\n</td>\n<td style=\"width: 154.6500pt; padding: 0.0000pt 5.4000pt 0.0000pt 5.4000pt; border-left: none; mso-border-left-alt: none; border-right: 1.0000pt solid #000000; mso-border-right-alt: 0.5000pt solid #000000; border-top: none; mso-border-top-alt: 0.5000pt solid #000000; border-bottom: 1.0000pt solid #000000; mso-border-bottom-alt: 0.5000pt solid #000000;\" valign=\"center\" nowrap=\"nowrap\" width=\"309\">\n<p class=\"MsoNormal\" style=\"mso-pagination: widow-orphan; text-align: center; vertical-align: middle; line-height: 150%; margin: 0.0000pt;\" align=\"center\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">具体内容详见谈判采购文件第五章采购需求</span></p>\n</td>\n<td style=\"width: 46.7000pt; padding: 0.0000pt 5.4000pt 0.0000pt 5.4000pt; border-left: none; mso-border-left-alt: none; border-right: 1.0000pt solid #000000; mso-border-right-alt: 0.5000pt solid #000000; border-top: none; mso-border-top-alt: 0.5000pt solid #000000; border-bottom: 1.0000pt solid #000000; mso-border-bottom-alt: 0.5000pt solid #000000;\" valign=\"center\" width=\"93\">\n<p class=\"MsoNormal\" style=\"mso-pagination: widow-orphan; text-align: center; vertical-align: middle; margin: 0.0000pt;\" align=\"center\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">1种</span><span style=\"font-family: 宋体; font-size: 10.5pt;\">1套</span></p>\n</td>\n<td style=\"width: 61.7500pt; padding: 0.0000pt 5.4000pt 0.0000pt 5.4000pt; border-left: none; mso-border-left-alt: none; border-right: 1.0000pt solid #000000; mso-border-right-alt: 0.5000pt solid #000000; border-top: none; mso-border-top-alt: 0.5000pt solid #000000; border-bottom: 1.0000pt solid #000000; mso-border-bottom-alt: 0.5000pt solid #000000;\" valign=\"center\" nowrap=\"nowrap\" width=\"123\">\n<p class=\"MsoNormal\" style=\"mso-pagination: widow-orphan; text-align: center; vertical-align: middle; margin: 0.0000pt;\" align=\"center\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">小保当矿</span></p>\n</td>\n<td style=\"width: 33.1000pt; padding: 0.0000pt 5.4000pt 0.0000pt 5.4000pt; border-left: none; mso-border-left-alt: none; border-right: 1.0000pt solid #000000; mso-border-right-alt: 0.5000pt solid #000000; border-top: none; mso-border-top-alt: 0.5000pt solid #000000; border-bottom: 1.0000pt solid #000000; mso-border-bottom-alt: 0.5000pt solid #000000;\" valign=\"center\" nowrap=\"nowrap\" width=\"66\">\n<p class=\"MsoNormal\" style=\"mso-pagination: widow-orphan; text-align: center; vertical-align: middle; margin: 0.0000pt;\" align=\"center\"><span style=\"font-family: 宋体; font-size: 10.5pt;\">&nbsp;</span></p>\n</td>\n</tr>\n</tbody>\n</table>\n</div>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%; mso-list: l0 level1 lfo1;\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; font-size: 10.5pt;\">2、&nbsp;</span><!--[endif]--><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">采购范围及相关要求</span></strong></h3>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; vertical-align: middle; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.1采购范围：本次购置</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">1套</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">110kV变电站故障录波、小电流接地选线装置及GIS综合在线监测系统</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">，</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">内容包括：故障录波供货配置清单（智能故障录波装置、故障录波安装辅料）；小电流接地选线装置配置清单包含（小电流接地选线装置、安装辅料），</span><span style=\"font-family: 宋体;\">1号2号站设备供货配置清单包含（微水监测传感器、微水监测IED、电源通讯电缆及安装附件、通信电缆及安装附件、三通连接件、葛兰头、封堵、金属软管、0型圈、电缆锁紧头、桥架开孔堵盖等），供货方负责该项目的设计、供货、安装工作，具体内容详见谈判采购文件第五章采购需求。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.2交货期：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">合同签订后</span><span style=\"font-family: 宋体;\">60天内到货并完成全部设备安装、调试、联试及投运工作</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.3交货地点：货物运至</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">小保当矿</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">甲方指定地点。</span></p>\n<p class=\"MsoBodyText\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: widow-orphan; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">2.4质保期：</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">货物验收合格之日起一年，并免费提供技术咨询</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"margin-left: 24.1000pt; text-indent: -21.1000pt; mso-char-indent-count: -2.0000; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3、供应商资格要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.1供应商应依法设立且满足如下要求：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><a name=\"OLE_LINK31\"></a><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><a name=\"OLE_LINK30\"></a><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">1）依法设立：必须为具有独立的法人资格的生产厂家，并提供加载统一社会信用代码的营业执照或事业单位法人证书，有效的开户许可证或有效的银行开户证明材料</span></span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">资质要求</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">：供应商须具有输变电工程专业承包三级及以上资质，同时具有承装类、承试类二级及以上的《承装（试）电力设施许可证》，及有效的安全生产许可证。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">3</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">）</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">项目负责人要求：拟派项目负责人应具有机电工程专业二级或以上注册建造师资格及有效的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">《安全生产考核合格证书》（</span><span style=\"font-family: 宋体;\">B类）且不得在其他在建项目担任项目负责人（提供无在建项目承诺书），项目负责人需为本单位在册职工，需提供2025年10月以后至少6个月的社保证明材料。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">（</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">4</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">）财务要求：必须提供（</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">3</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">-202</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">5</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; font-size: 10.5000pt;\">年）连续三年经第三方审计的财务报告，若公司成立时间不足三年，可提供成立之后年份经第三方审计的财务报告。</span></p>\n<p class=\"MsoToc2\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">（</span><span style=\"font-family: 宋体;\">5）业绩要求：应具有近年（自2022年1月1日至谈判截止日期）至少3项同类设备安装（故障录波、小电流接地选线、GIS综合在线监测任一均可）业绩（以合同及发票为准，发票需清晰明了完整，不得遮挡，每份合同对应的增值税发票不少于1张，对应的增值税发票在国家税务总局全国增值税发票查验平台核验必须真实、有效，合同必须有签订时间页及双方盖章页，合同复印件应清晰明了，可以看清合同内容，甲乙双方盖章完整，有效业绩时间以合同签订时间为准）。</span></span></p>\n<p class=\"19\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">（</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">6</span><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">）信誉要求（以供应商加盖公章的承诺书或相关证明材料为准）：</span></p>\n<p class=\"19\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">未被国家企业信用信息公示系统（</span><span style=\"font-family: 宋体;\">http://www.gsxt.gov.cn/index.html）列入严重违法失信名单（黑名单）。</span></span></p>\n<p class=\"19\" style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">未被列入</span><span style=\"font-family: 宋体;\">&ldquo;信用中国&rdquo;（http://www.creditchina.gov.cn/）严重失信主体名单。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">3.2供应商不得存在下列情形之一（提供承诺书或相关证明材料）：</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\">处于被责令停产停业、暂扣或者吊销执照、暂扣或者吊销许可证、吊销资质证书状态；进入清算程序，或被宣告破产，或其他丧失履约能力的情形。</span><u></u></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">3.3本次采购不接受联合体。</span><a name=\"_Toc10688\"></a></span></p>\n<h3 style=\"margin-top: 0.0000pt; margin-bottom: 0.0000pt; line-height: 150%;\"><a name=\"_Toc10856\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; font-size: 1