INSERT INTO `bidding_notice_external` VALUES (2097380028083998722,'','2026-09-10 09:35:06','','2026-09-10 09:36:13',_binary '\0','QYZB','秦源电子招标平台','陕西煤业物资榆通有限责任公司柠条塔矿井下主要加压泵房变频器及控制系统更新（控制）项目采购询比采购公告','https://qyzb.shccmg.com/cms/default/webfile/2ywgg/20260717/1262868176589291520.html','95e0e86045eaa3246919efdd72c33d04af277ba6317a684fa0c46a8aa3ee450d',NULL,'HTML','<p class=\"16\" style=\"text-indent: 0.0000pt; text-autospace: ideograph-numeric; page-break-after: avoid; mso-pagination: lines-together; text-align: center; line-height: 150%; margin: 0.0000pt;\" align=\"center\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 18pt;\">询比采购公告</span></strong></p>\n<p class=\"18\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">柠条塔矿井下主要加压泵房变频器及控制系统更新（控制）项目采购</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">，采购人为陕西煤业物资榆通有限责任公司，项目资金来自企业自筹，出资比例为</span><span style=\"font-family: 宋体;\">100%。项目</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">已</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">具备采购条件，陕西秦源招标有限责任公司受陕西煤业物资榆通有限责任公司委托，现公开邀请供应商参加询比采购活动，相关事项告知如下：</span><u></u></p>\n<p class=\"18\" style=\"margin: 0pt; text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">1</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购项目简介</span></strong></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">1.1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">采购项目名称：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">柠条塔矿井下主要加压泵房变频器及控制系统更新（控制）项目采购（采</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">购编号：</span><span style=\"font-family: 宋体;\">0866-26E2SXQY0664）</span></span></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">1.2</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">釆购人：陕西煤业物资榆通有限责任公司</span></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">1.3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">釆</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">机构：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">陕西秦源招标有限责任公司</span></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1.4</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">釆购项目资金落实情况：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">企业自筹，比例</span><span style=\"font-family: 宋体;\">100%</span></span></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1.5</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">采购项目概况：</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">本项目为陕煤集团神木柠条塔矿业井下主要加压泵房控制系统更新改造项目，适配井下含瓦斯、煤尘的爆炸性环境。项目对三处井下恒压供水泵房开展自动化升级，采购</span><span style=\"font-family: 宋体;\">PLC控制箱、防爆电源、各类矿用传感器、电动阀门、摄像仪及配套线缆辅材，定制开发排水集控系统软件。改造后系统具备就地、自动、远程、检修四种控制模式，可实现恒压供水、水泵轮换、故障保护、视频联动及数据联网上传，达成泵房无人值守智能管控。</span></span></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; mso-outline-level: 3; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">.</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6成交供应商数量及成交份额：一家，100%</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">&nbsp;<span style=\"font-family: 宋体;\">。</span></span></p>\n<p class=\"18\" style=\"margin: 0pt; text-indent: 21.1pt; line-height: 150%;\"><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">采购范围及相关要求</span></strong></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.1采</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">购范围：矿用隔爆兼本安型可编程控制</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; line-height: 150%; letter-spacing: 0.0000pt; font-size: 10.5000pt;\"><span style=\"font-family: 宋体;\">箱</span><span style=\"font-family: 宋体;\">3套，矿用隔爆兼本安型锂离子蓄电池电源、</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">矿用本安型操作台、煤矿供排水监控系统软件</span><span style=\"font-family: 宋体;\">1套、传感器一批、控制电缆及软件等。供货范围包含设备供货、系统设计、制造（含所需软件）、检验、试验、包装、运输（装卸）、随机标准附件、备品备件及专用工具、技术资料、现场安装指导、调试、试运转、人员培训及系统联网接入服务，与服务并配合完成整套设备性能考核验收、售后服务及质保期内的维修和保养等为实施本项目所需的全部工作内容，具体内容及要求详见招标文件第五章供货要求。</span></span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.2</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">交货期：合同签订</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">生效</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">后</span><span style=\"font-family: 宋体;\">40个工作日内到矿</span></span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.3</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">交货地点：</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">柠条塔煤矿</span><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"MsoNormal\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; line-height: 150%;\"><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">2.4质保期：运行12个月或验收通过后18个月。</span></p>\n<p class=\"20\" style=\"margin: 0pt; text-indent: 21.1pt; break-after: avoid; line-height: 150%;\"><a name=\"_Toc219\"></a><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">3</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">.</span></strong><strong><span style=\"font-family: 宋体; line-height: 150%; letter-spacing: 0pt; font-size: 10.5pt;\">供应商资格要求</span></strong></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3.1</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商应满足如下要求：</span></p>\n<p class=\"17\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-size: 10.5pt;\">（1）</span><!--[endif]--><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">依法设立</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">必须是在中华人民共和国境内注册的独立法人</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">的矿用隔爆兼本安型可编程控制箱、煤矿排水监控系统、矿用本安型操作台生产厂家，</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">具备有效的企业法人营业执照</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">，提供开户许可证或基本存款账户信息证明材料</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"17\" style=\"mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; mso-list: l0 level1 lfo1; margin: 0.0000pt;\" align=\"justify\"><!-- [if !supportLists]--><span style=\"font-family: 宋体; letter-spacing: 0pt; font-weight: bold; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">（2）</span><!--[endif]--><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">资质要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">需提供煤矿排水监控系统</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">煤矿安全标志证书。</span></p>\n<p class=\"17\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">财务要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">必须提供（</span><span style=\"font-family: 宋体;\">202</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">年</span><span style=\"font-family: 宋体;\">-202</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">5</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">年）连续三年经第三方审计的财务报告，若公司成立时间不足三年，可提供成立之后年份经第三方审计的财务报告。</span></p>\n<p class=\"17\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">4</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">业绩要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">应具有近年（自</span><span style=\"font-family: 宋体;\">2023年1月1日至</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">截止日期）至少三项</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; font-size: 10.5pt;\">排水控制系统</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; letter-spacing: 0.0000pt; font-size: 10.5000pt;\">销售</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">业绩（业绩以合同及合同对应的任意一张增值税发票为准，对应的增值税发票在国家税务总局全国增值税发票查验平台核验必须真实、有效，合同必须有双方盖章页、首页、供货清单，合同内容清晰，甲乙双方盖章完整，有效业绩时间以合同签订时间为准）。</span></p>\n<p class=\"17\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">5</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">信誉要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">未被国家企业信用信息公示系统（</span><span style=\"font-family: 宋体;\">http://www.gsxt.gov.cn/index.html）列入严重违法失信名单（黑名单）</span></span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\"><span style=\"font-family: 宋体;\">；未被列入</span><span style=\"font-family: 宋体;\">&ldquo;信用中国&rdquo;（http://www.creditchina.gov.cn/）严重失信主体名单。</span></span></p>\n<p class=\"17\" style=\"margin-top: 0.0000pt; margin-right: 0.0000pt; margin-bottom: 0.0000pt; mso-para-margin-right: 0.0000gd; mso-para-margin-left: 0.0000gd; text-indent: 21.1000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%;\" align=\"justify\"><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">（</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">6</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">）</span></strong><strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">其他要求：</span></strong><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">法定代表人为同一个人的两个及两个以上法人，母公司、全资子公司及其控股公司，都不得同时</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">参加</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">询比采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">。</span></p>\n<p class=\"17\" style=\"margin-top: 0pt; margin-right: 0pt; margin-bottom: 0pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3.2</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">供应商不得存在下列情形之一：（提供承诺书或相关证明材料）</span></p>\n<p class=\"17\" style=\"text-indent: 21.0000pt; mso-char-indent-count: 2.0000; text-autospace: ideograph-numeric; mso-pagination: none; text-align: justify; text-justify: inter-ideograph; line-height: 150%; margin: 0.0000pt;\" align=\"justify\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">处于被责令停产停业、暂扣或者吊销执照、暂扣或者吊销许可证、吊销资质证书状态；进入清算程序，或被宣告破产，或其他丧失履约能力的情形；</span></p>\n<p class=\"17\" style=\"margin: 0pt; text-indent: 21pt; line-height: 150%;\"><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">.3</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">本次采购</span><span style=\"font-family: 宋体; letter-spacing: 0pt; font-size: 10.5pt;\">不接受</span><span style=\"font-family: 宋体;